window.C1_DATA={"course":{"title":"Deutsch C1","subtitle":"Türkçe → Almanca · Deutsch-Test für den Beruf C1","version":"c1-6-dtb"},"lessons":[{"id":1,"unit":"C1 temeli","title":"C1 düzeyi ve DTB C1 sınav stratejisi","skills":["Strateji","Okuma","Dinleme"],"goal":"C1 düzeyindeki dil beklentilerini Deutsch-Test für den Beruf C1’in işyeri odaklı görevleriyle ilişkilendirmek.","explanation":"C1 düzeyinde amaç yalnızca ileri dilbilgisi değildir: uzun ve yoğun metinleri anlamak, örtük anlamı yakalamak, resmî ve yarı resmî kayıtları yönetmek, işyerinde sorun çözmek, bilgiyi başka bir kişiye aktarmak ve düşünceyi ikna edici biçimde yapılandırmak gerekir. Hedef sınav Deutsch-Test für den Beruf C1 olduğu için bu kursta özellikle işyeri iletişimi, arabuluculuk/aktarım (Mediation), müşteri yazışmaları, telefon notları, toplantı dili ve çözüm odaklı konuşma öne çıkar.","examples":[["Die Lieferverzögerung lässt sich voraussichtlich bis Freitag beheben.","Teslimat gecikmesi muhtemelen cuma gününe kadar giderilebilir.","İşyerinde temkinli ve çözüm odaklı ifade."],["Ich fasse kurz zusammen, was der Kunde telefonisch mitgeteilt hat.","Müşterinin telefonda ilettiklerini kısaca özetliyorum.","DTB’de önemli olan bilgi aktarımı / Mediation."]],"quiz":[{"q":"DTB C1’de hangi alan özellikle önemlidir?","o":["Yalnızca akademik makale yazmak","İşyeri bağlamında bilgiyi anlayıp uygun biçimde aktarmak ve çözüm üretmek","Sadece tek tek kelime ezberlemek"],"a":1,"why":"Sınav genel mesleki Almancayı, işyeri iletişimini ve bazı görevlerde Mediation/aktarım becerisini ölçer."},{"q":"C1 düzeyinde iyi bir çalışma yaklaşımı hangisidir?","o":["Kalıpları bağlamdan bağımsız ezberlemek","Dilbilgisi, kelime, kayıt ve iletişim işlevlerini gerçek işyeri görevleri içinde birleştirmek","Yalnızca çoktan seçmeli soru çözmek"],"a":1,"why":"Üretim ve etkileşim görevleri dil araçlarının bağlam içinde kullanılmasını gerektirir."}]},{"id":2,"unit":"C1 temeli","title":"Metin örgüsü: gönderim ve bağdaşıklık","skills":["Okuma","Yazma"],"goal":"Uzun metinlerde zamir, gönderim ve bağlayıcıların neye işaret ettiğini izlemek.","explanation":"C1 okuma sorularında doğru cevap çoğu zaman tek bir cümlede değildir. “dies”, “dabei”, “dadurch”, “Letzteres”, “ein solcher Ansatz” gibi ifadeler önceki bilgiyi yeniden paketler. Yazarken de aynı ismi tekrar etmek yerine kontrollü gönderim kullanmak metni daha olgun gösterir.","examples":[["Viele Hochschulen führen hybride Formate ein. Dadurch können auch Berufstätige teilnehmen.","Birçok üniversite hibrit format getiriyor. Böylece çalışanlar da katılabiliyor.","“Dadurch” önceki eylemin sonucunu kurar."],["Es gibt zwei Modelle: Präsenzpflicht und freie Teilnahme. Letzteres bietet mehr Flexibilität.","İki model var: zorunlu yüz yüze ve serbest katılım. İkincisi daha fazla esneklik sunar.","“Letzteres” ikinci unsura gönderme yapar."]],"quiz":[{"q":"“Letzteres” hangi unsura gönderme yapar?","o":["İlk söylenene","Son söylenene","Bütün paragrafa"],"a":1,"why":"Letzteres = sonuncu / ikinci anılan unsur."},{"q":"“Dadurch” en sık hangi ilişkiyi kurar?","o":["Sonuç / araç","Zaman","Alıntı"],"a":0,"why":"Dadurch, önceki durumdan doğan sonucu veya aracı belirtir."}]},{"id":3,"unit":"C1 temeli","title":"Argümantasyon ve bağlaçlar","skills":["Yazma","Konuşma"],"goal":"Karşıtlık, neden, sonuç, taviz ve sınırlama ilişkilerini hassas biçimde kurmak.","explanation":"C1 metinlerinde “aber” ve “weil” tek başına yeterli değildir. İlişkiyi doğru türde kurmak gerekir: “zwar … jedoch”, “wenngleich”, “insofern als”, “folglich”, “demgegenüber”, “unter der Voraussetzung, dass”. Bağlaç çeşitliliği ancak anlam doğruysa puan getirir.","examples":[["Wenngleich die Datenbasis klein ist, sind die Ergebnisse bemerkenswert.","Veri tabanı küçük olmakla birlikte sonuçlar dikkat çekicidir.","Taviz ilişkisi."],["Die Nachfrage sank deutlich; folglich wurde das Angebot reduziert.","Talep belirgin biçimde düştü; bunun sonucunda arz azaltıldı.","Sonuç ilişkisi."]],"quiz":[{"q":"Hangi bağlaç taviz (concession) bildirir?","o":["folglich","wenngleich","infolgedessen"],"a":1,"why":"Wenngleich = her ne kadar / olsa da."},{"q":"“demgegenüber” en uygun hangi işlevdedir?","o":["Karşılaştırmalı karşıtlık","Sebep","Amaç"],"a":0,"why":"Demgegenüber iki görüş veya olguyu karşı karşıya getirir."}]},{"id":4,"unit":"C1 temeli","title":"Parafraz ve anlam inceliği","skills":["Okuma","Yazma"],"goal":"Aynı fikri farklı sözcük ve yapılarla, anlamı bozmadan yeniden ifade etmek.","explanation":"Goethe ve telc C1’de seçenekler metindeki ifadeyi çoğu zaman aynen tekrar etmez. “zurückgehen auf” ile “bedingt sein durch”, “in Betracht ziehen” ile “berücksichtigen”, “kaum zu überschätzen” ile “von großer Bedeutung sein” arasındaki ilişkiyi görmek gerekir. Üretimde de aynı sözcüğü tekrar etmek yerine kontrollü parafraz kullan.","examples":[["Der Rückgang ist auf mehrere Faktoren zurückzuführen.","Düşüş birden fazla faktöre bağlanabilir.","Nedensellik parafrazı."],["Diese Entwicklung darf nicht außer Acht gelassen werden.","Bu gelişme göz ardı edilmemelidir.","Resmî/akademik ifade."]],"quiz":[{"q":"“etwas in Betracht ziehen” en yakın hangi anlama gelir?","o":["etwas ablehnen","etwas berücksichtigen","etwas beweisen"],"a":1,"why":"Her ikisi de bir unsuru değerlendirmeye katmak demektir."},{"q":"“nicht außer Acht lassen” ne demektir?","o":["göz ardı etmemek","reddetmek","abartmak"],"a":0,"why":"Bir faktörü dikkate almaya devam etmek anlamındadır."}]},{"id":5,"unit":"C1 temeli","title":"Kayıt ve üslup: resmî, nötr, konuşma dili","skills":["Yazma","Konuşma"],"goal":"Duruma göre uygun kayıt seçmek ve üslup kırılmalarını önlemek.","explanation":"C1’de yalnızca doğru cümle kurmak değil, cümlenin bağlama uygun olması beklenir. Bir foruma “Meines Erachtens …” ile yazılabilir; yarı resmî e-postada “Ich möchte Sie darauf aufmerksam machen, dass …” uygundur. “Das ist total blöd” gibi ifadeler resmî bağlamda uygun değildir.","examples":[["Ich möchte Sie darauf aufmerksam machen, dass die vereinbarte Frist bereits abgelaufen ist.","Kararlaştırılan sürenin dolduğuna dikkatinizi çekmek isterim.","Yarı resmî/resmî."],["Aus meiner Sicht überwiegen die Vorteile.","Bana göre avantajlar ağır basıyor.","Nötr argümantatif kayıt."]],"quiz":[{"q":"Bir iş e-postasında en uygun ifade hangisidir?","o":["Das nervt echt.","Ich möchte Sie auf ein Problem aufmerksam machen.","Krass, das geht gar nicht."],"a":1,"why":"Duruma uygun, nazik ve açık bir kayıt kullanır."},{"q":"“Meines Erachtens” hangi işlevi görür?","o":["Görüş belirtme","Özür dileme","Alıntı yapma"],"a":0,"why":"Resmî/nötr biçimde kişisel görüş belirtir."}]},{"id":6,"unit":"C1 temeli","title":"Eşdizimler ve işlevsel fiil yapıları","skills":["Kelime","Yazma","Okuma"],"goal":"Tek tek kelime yerine doğal sözcük birliklerini ve akademik kalıpları kullanmak.","explanation":"C1’de sözcük bilgisi “çok kelime bilmekten” çok, doğru kelimeleri birlikte kullanabilmektir. “eine Entscheidung treffen”, “in Kraft treten”, “zur Verfügung stehen”, “Kritik üben”, “Maßnahmen ergreifen” gibi kalıplar doğal ve yoğun bir anlatım sağlar.","examples":[["Die Universität ergreift Maßnahmen gegen Prüfungsbetrug.","Üniversite sınav hilesine karşı önlemler alıyor.","“Maßnahmen ergreifen” sabit eşdizim."],["Die neue Regelung tritt im Januar in Kraft.","Yeni düzenleme ocakta yürürlüğe giriyor.","“in Kraft treten” sabit kalıp."]],"quiz":[{"q":"Doğal eşdizim hangisidir?","o":["eine Entscheidung machen","eine Entscheidung treffen","eine Entscheidung bauen"],"a":1,"why":"Standart Nomen-Verb-Verbindung “eine Entscheidung treffen”dir."},{"q":"“Kritik üben an” ne demektir?","o":["eleştirmek","desteklemek","erteleme yapmak"],"a":0,"why":"Bir konu veya kişiyi eleştirmek anlamındadır."}]},{"id":7,"unit":"C1 dilbilgisi","title":"Süreç edilgeni (Vorgangspassiv): süreç ve perspektif","skills":["Dilbilgisi","Yazma"],"goal":"Vorgangspassiv’i tüm temel zamanlarda ve farklı cümle türlerinde güvenli kullanmak.","explanation":"Vorgangspassiv “werden + Partizip II” ile bir sürece odaklanır. Fail gerekirse “von + Dativ” veya özellikle sebep/araç için “durch + Akkusativ” ile verilir. Perfektte “ist … worden” kullanılır; “geworden” değil.","examples":[["Die Ergebnisse werden morgen veröffentlicht.","Sonuçlar yarın yayımlanacak.","Präsens pasif."],["Die Daten sind mehrfach überprüft worden.","Veriler birkaç kez kontrol edildi.","Perfekt pasif."]],"quiz":[{"q":"Doğru Perfekt-Passiv hangisidir?","o":["Die Daten sind geprüft geworden.","Die Daten sind geprüft worden.","Die Daten haben geprüft worden."],"a":1,"why":"Vorgangspassiv Perfekt: sein + Partizip II + worden."},{"q":"“durch” en çok ne zaman uygundur?","o":["İnsan faili belirtirken her zaman","Nedensel/araçsal bir etkeni belirtirken","Zaman belirtirken"],"a":1,"why":"Örn. “durch einen Fehler verursacht”."}]},{"id":8,"unit":"C1 dilbilgisi","title":"Durum edilgeni (Zustandspassiv) ve öznesiz pasif","skills":["Dilbilgisi","Yazma"],"goal":"Sonuç durumu ile süreci ayırmak ve Akkusativobjekt olmadan pasif kurmak.","explanation":"Zustandspassiv “sein + Partizip II” ile ortaya çıkmış durumu anlatır: “Die Tür ist geschlossen.” Süreç “Die Tür wird geschlossen.” şeklindedir. Akkusativ nesnesi olmayan fiillerde de öznesiz pasif mümkündür: “Den Betroffenen wurde geholfen.”","examples":[["Der Antrag ist bereits genehmigt.","Başvuru hâlihazırda onaylanmış durumda.","Durum."],["Über den Vorschlag wurde lange diskutiert.","Öneri uzun süre tartışıldı.","Öznesiz Vorgangspassiv."]],"quiz":[{"q":"Hangisi Zustandspassiv’dir?","o":["Die Tür wird geschlossen.","Die Tür ist geschlossen.","Man schließt die Tür."],"a":1,"why":"sein + Partizip II sonuç durumunu gösterir."},{"q":"Doğru öznesiz pasif hangisidir?","o":["Den Gästen wurden geholfen.","Den Gästen wurde geholfen.","Die Gäste wurde geholfen."],"a":1,"why":"Gizli “es” nedeniyle fiil tekil kalır."}]},{"id":9,"unit":"C1 dilbilgisi","title":"İsim-fiil birleşimleri (Nomen-Verb-Verbindungen)","skills":["Dilbilgisi","Kelime"],"goal":"Serbest Nomen-Verb-Verbindungen ile Funktionsverbgefüge’yi tanımak ve kullanmak.","explanation":"C1’de birçok soyut eylem ad + fiil kalıbıyla ifade edilir. Bazıları gerçek anlamlıdır (“eine Frage stellen”), bazıları işlevsel fiil yapısıdır (“zur Sprache bringen”, “in Erwägung ziehen”). Bunlar özellikle resmî ve akademik metinlerde sık görülür.","examples":[["Der Vorschlag kam erneut zur Sprache.","Öneri tekrar gündeme geldi.","Funktionsverbgefüge."],["Wir ziehen eine Verlängerung der Frist in Erwägung.","Süre uzatımını değerlendiriyoruz.","Resmî ifade."]],"quiz":[{"q":"“in Erwägung ziehen” ne demektir?","o":["göz önünde bulundurmak","reddetmek","yasaklamak"],"a":0,"why":"Bir seçeneği ciddi biçimde değerlendirmeye almak."},{"q":"Doğal kalıp hangisidir?","o":["Kritik machen","Kritik üben","Kritik nehmen"],"a":1,"why":"Standart kalıp “Kritik üben (an + Dat.)”."}]},{"id":10,"unit":"C1 dilbilgisi","title":"Kip fiilleri (Modalverben): nesnel anlamlar","skills":["Dilbilgisi","Yazma"],"goal":"Zorunluluk, izin, olanak, istek ve görev anlamlarını doğru modal fiille aktarmak.","explanation":"Nesnel kullanımda modalite özne ve eyleme ilişkindir: “müssen” zorunluluk, “dürfen” izin/yasak, “können” yetenek/olanak, “sollen” görev/beklenti, “wollen” niyet bildirir. Perfektte Ersatzinfinitiv görülür: “hat teilnehmen können”.","examples":[["Die Teilnehmenden müssen sich vorher anmelden.","Katılımcılar önceden kayıt olmak zorunda.","Zorunluluk."],["Wir haben die Frist verlängern können.","Süreyi uzatabildik.","Ersatzinfinitiv."]],"quiz":[{"q":"“Es ist nicht notwendig” hangi modal yapıyla verilebilir?","o":["nicht müssen","nicht dürfen","sollen"],"a":0,"why":"nicht müssen = zorunlu olmamak; nicht dürfen = yasak olmak."},{"q":"Doğru Perfekt hangisidir?","o":["Wir haben kommen gekonnt.","Wir haben kommen können.","Wir sind kommen können."],"a":1,"why":"Modal fiilde Perfekt çoğunlukla Ersatzinfinitiv kullanır."}]},{"id":11,"unit":"C1 dilbilgisi","title":"Kip fiilleri (Modalverben): öznel anlam ve kanıt derecesi","skills":["Dilbilgisi","Okuma"],"goal":"Tahmin, çıkarım, söylenti ve şüpheli iddia gibi öznel modal anlamları çözmek.","explanation":"C1 metinlerinde modal fiiller kanıt derecesini kodlar. “muss” güçlü çıkarım, “dürfte” olası varsayım, “könnte” zayıf olasılık, “soll” başkasından duyulan bilgi, “will” konuşanın mesafeli yaklaştığı öz iddia anlamına gelebilir.","examples":[["Die Ursache dürfte im veränderten Konsumverhalten liegen.","Neden muhtemelen değişen tüketim davranışında yatıyor.","Olası varsayım."],["Der Minister soll von den Problemen gewusst haben.","Bakanın sorunları bildiği söyleniyor.","İkinci el bilgi/söylenti."]],"quiz":[{"q":"“Er soll davon gewusst haben.” en yakın anlam hangisidir?","o":["Kesin biliyorum.","Duyduğuma göre biliyormuş.","Bilmesi yasaktı."],"a":1,"why":"Öznel “sollen” doğrulanmamış/ikinci el bilgiyi aktarır."},{"q":"En güçlü çıkarım hangisidir?","o":["könnte","dürfte","muss"],"a":2,"why":"Öznel “müssen” konuşanın çok güçlü çıkarımını gösterir."}]},{"id":12,"unit":"C1 dilbilgisi","title":"Dilek/varsayım kipi (Konjunktiv II): varsayım, ihtiyat ve geçmiş pişmanlık","skills":["Dilbilgisi","Konuşma","Yazma"],"goal":"Gerçek dışı koşullar, temkinli ifadeler, öneriler ve geçmişte gerçekleşmeyen durumları ifade etmek.","explanation":"Konjunktiv II C1’de yalnızca “würde” cümlesi değildir. “Wäre die Nachfrage höher, ließe sich das Projekt finanzieren.” gibi yoğun yapılar, temkinli iddialar (“Es wäre denkbar, dass …”) ve geçmiş pişmanlık (“Man hätte früher reagieren müssen.”) önemlidir.","examples":[["Wäre mehr Zeit vorhanden, ließe sich die Analyse vertiefen.","Daha fazla zaman olsaydı analiz derinleştirilebilirdi.","İrreal koşul."],["Man hätte die Risiken früher berücksichtigen sollen.","Riskler daha erken dikkate alınmalıydı.","Geçmişe dönük değerlendirme."]],"quiz":[{"q":"Geçmişte gerçekleşmeyen öneri hangisidir?","o":["Man sollte reagieren.","Man hätte reagieren sollen.","Man soll reagieren."],"a":1,"why":"Konjunktiv II Vergangenheit geçmişe dönük tavsiye/eleştiri yapar."},{"q":"“Es wäre denkbar, dass …” ne tür bir işlev taşır?","o":["Temkinli varsayım","Kesin emir","Söylenti aktarma"],"a":0,"why":"İddiayı ihtiyatlılaştırır."}]},{"id":13,"unit":"C1 dilbilgisi","title":"Dolaylı anlatım kipi (Konjunktiv I)","skills":["Dilbilgisi","Okuma","Yazma"],"goal":"Başkasının sözünü mesafeli biçimde aktarmak ve haber dilini anlamak.","explanation":"Konjunktiv I, özellikle haber ve akademik aktarımda kaynağın sözünü konuşanın kendi iddiası gibi sunmamasını sağlar: “Die Autorin erklärt, die Daten seien eindeutig.” Biçim Indikativ ile çakışıyorsa çoğu zaman Konjunktiv II devreye girer.","examples":[["Der Forscher betont, die Ergebnisse seien vorläufig.","Araştırmacı sonuçların geçici olduğunu vurguluyor.","Dolaylı anlatım."],["Die Zeugen erklärten, sie hätten nichts bemerkt.","Tanıklar hiçbir şey fark etmediklerini söylediler.","Çakışmayı önlemek için Konjunktiv II."]],"quiz":[{"q":"Dolaylı anlatım için en tipik yapı hangisidir?","o":["Er sagt, er ist krank.","Er sagt, er sei krank.","Er sagt, krank sein."],"a":1,"why":"Konjunktiv I mesafeli aktarım sağlar."},{"q":"Konjunktiv I’in temel iletişim işlevi nedir?","o":["Kaynağın sözünü mesafeli aktarmak","Emir vermek","Gelecek zaman kurmak"],"a":0,"why":"Konuşan aktarılan bilgiye doğrudan sahiplik iddiası eklemez."}]},{"id":14,"unit":"C1 dilbilgisi","title":"Adlaştırma ve fiilleştirme","skills":["Dilbilgisi","Yazma","Okuma"],"goal":"Yoğun isim yapıları ile açık fiil cümleleri arasında dönüşüm yapmak.","explanation":"Akademik ve resmî metinler sık sık nominal yapı kullanır: “wegen der steigenden Kosten”. Daha akıcı anlatım için fiilleştirilebilir: “weil die Kosten steigen”. Ters yönde dönüşüm de metni yoğunlaştırır. Doğru edat ve hâl seçimi kritik önemdedir.","examples":[["Aufgrund der starken Nachfrage wurde das Angebot erweitert.","Yüksek talep nedeniyle teklif genişletildi.","Nominal yapı."],["Weil die Nachfrage stark gestiegen ist, wurde das Angebot erweitert.","Talep çok arttığı için teklif genişletildi.","Fiilleştirilmiş yapı."]],"quiz":[{"q":"“wegen der Verzögerung” için uygun fiil cümlesi hangisidir?","o":["weil sich etwas verzögert","obwohl sich etwas verzögert","damit sich etwas verzögert"],"a":0,"why":"“wegen” neden bildirir; “weil” ile fiilleştirilebilir."},{"q":"Nominalizasyonun tipik etkisi nedir?","o":["Metni yoğunlaştırır ve resmîleştirebilir","Her zaman konuşma dilini artırır","Fiil zamanını kaldırdığı için anlamı yok eder"],"a":0,"why":"Özellikle akademik/resmî yazıda bilgi yoğunluğunu artırır."}]},{"id":15,"unit":"DTB C1 sınav yapısı","title":"Sınav akışı, puanlama ve Mediation","skills":["Strateji","Sınav"],"goal":"135 dakikalık yazılı sınavı, 16 dakikalık sözlü sınavı ve dört becerinin 60’ar puanlık ağırlığını anlamak.","explanation":"Deutsch-Test für den Beruf C1’de yazılı bölüm toplam 135 dakikadır: Lesen + Lesen und Schreiben 65 dakika, Hören + Hören und Schreiben yaklaşık 25 dakika ve Sprachbausteine und Schreiben 45 dakika. Sözlü sınav yaklaşık 16–17 dakika sürer ve hazırlık süresi yoktur. Lesen, Hören, Schreiben ve Sprechen ayrı ayrı 60 puandır. Bazı görevler iki beceriyi birleştirir; örneğin bir şikâyeti okuyup müşteriye uygun bir e-posta yazmak veya telefon mesajını dinleyip meslektaşa not aktarmak.","examples":[["Lesen und Schreiben verbindet Verstehen und adressatengerechtes Reagieren.","Okuma ve yazma, anlamayı uygun tepkiyle birleştirir.","Entegre görev mantığı."],["Es gibt keine Vorbereitungszeit für die mündliche Prüfung.","Sözlü sınav için hazırlık süresi yoktur.","Spontan üretim gerekir."]],"quiz":[{"q":"Yazılı DTB C1 sınavı toplam ne kadar sürer?","o":["90 dakika","135 dakika","180 dakika"],"a":1,"why":"Yazılı bölüm toplam 135 dakikadır."},{"q":"Sözlü sınavdan önce resmî hazırlık süresi var mı?","o":["Evet, 20 dakika","Evet, 10 dakika","Hayır"],"a":2,"why":"DTB C1 sözlü sınavında hazırlık süresi yoktur."}]},{"id":16,"unit":"DTB C1 okuma","title":"Lesen Teil 1: iş piyasası bilgilerini eşleştirme","skills":["Okuma","Parafraz"],"goal":"Beş kişinin ihtiyacını sekiz kısa iş/ekonomi metnindeki ana fikirlerle eşleştirmek.","explanation":"Bu bölümde ayrıntıdan önce ihtiyaç ile metnin işlevini eşleştirmek gerekir. Soruda kullanılan ifade ile metin genellikle aynı kelimeleri kullanmaz. “berufliche Neuorientierung” bir metinde “neue Perspektiven im Job” olarak parafraz edilebilir. Önce her kişi için 2–3 anahtar kavram çıkar, sonra sekiz metni hızlıca tara.","examples":[["Sie sucht eine Möglichkeit, ihre Arbeitszeit flexibler zu gestalten.","Çalışma saatlerini daha esnek düzenleme imkânı arıyor.","İhtiyaç cümlesi."],["Der Artikel zeigt Modelle für variable Schichtplanung.","Makale değişken vardiya planlama modellerini gösteriyor.","Parafraz eşleşmesi."]],"quiz":[{"q":"Bu bölümde en önemli strateji hangisidir?","o":["Her metni baştan sona ayrıntılı çevirmek","Kişinin ihtiyacını anahtar kavramlarla özetleyip metinlerde parafrazını bulmak","Sadece başlığa bakmak"],"a":1,"why":"Görev hızlı seçici okuma ve parafraz eşleştirmesi gerektirir."},{"q":"Beş soru için kaç aday metin vardır?","o":["5","6","8"],"a":2,"why":"Resmî formatta 5 eşleştirme için a–h, yani 8 aday vardır."}]},{"id":17,"unit":"DTB C1 okuma","title":"Lesen Teil 2: talimat ve işyeri kurallarını anlama","skills":["Okuma","Ayrıntı"],"goal":"İşyeri talimatlarında hem doğru/yanlış hem de ayrıntılı çoktan seçmeli soruları güvenli çözmek.","explanation":"Talimat, veri koruma, şirket kartı, güvenlik veya yan faaliyet gibi metinlerde modal fiiller ve koşullar belirleyicidir: “muss”, “darf”, “kann”, “sollte”, “nur wenn”. Bir seçenekte zorunluluk derecesi değişmişse cevap yanlış olabilir. “kann” ile “muss” arasındaki farkı özellikle kontrol et.","examples":[["Nebentätigkeiten müssen vorher schriftlich gemeldet werden.","Yan işler önceden yazılı bildirilmelidir.","Zorunluluk."],["Der Ausweis kann zum Bezahlen genutzt werden.","Kart ödeme için kullanılabilir.","İmkân, zorunluluk değil."]],"quiz":[{"q":"Metinde “kann verwendet werden” yazıyorsa hangi seçenek şüphelidir?","o":["kullanılabilir","kullanılması zorunludur","bir kullanım imkânıdır"],"a":1,"why":"“kann” imkân bildirir, zorunluluk değil."},{"q":"Bu bölüm kaç okuma itemi içerir?","o":["4","6","8"],"a":0,"why":"2 doğru/yanlış + 2 üç seçenekli soru = 4 item."}]},{"id":18,"unit":"DTB C1 okuma","title":"Lesen Teil 3: çalışma koşulları ve tavsiye eşleştirme","skills":["Okuma","Nüans"],"goal":"Dört işyeri sorusunu altı forum yanıtı/tavsiye ile eşleştirmek ve gerektiğinde “x” seçmek.","explanation":"Burada aynı tema yetmez; tavsiyenin gerçekten sorunu çözmesi gerekir. Bir soru fazla mesai hakkıyla ilgiliyse yalnızca “stres”ten bahseden bir yanıt yeterli değildir. Ayrıca bir veya iki soru için uygun tavsiye olmayabilir. Bu nedenle “x” gerçek bir seçenektir, son çare değildir.","examples":[["Wie kann ich Beruf und Familie besser vereinbaren?","İş ve aileyi nasıl daha iyi dengeleyebilirim?","Sorun."],["Eine frühere Arbeitszeit könnte den täglichen Stau vermeiden.","Daha erken çalışma saati günlük trafiği önleyebilir.","Uygun çözüm."]],"quiz":[{"q":"Bir cevap aynı temayı konuşuyor ama sorunun sorununa çözüm sunmuyorsa ne yapmalısın?","o":["Yine de eşleştirmek","Daha uygun cevap aramak veya x seçeneğini değerlendirmek","İlk gördüğünü seçmek"],"a":1,"why":"Eşleşme konu değil, iletişim amacı ve içerik çözümü üzerinden yapılır."},{"q":"Bu bölümde kaç soru vardır?","o":["4","5","6"],"a":0,"why":"Dört soru, altı aday cevap bulunur."}]},{"id":19,"unit":"DTB C1 okuma","title":"Lesen Teil 4: toplantı tutanağı ve görev dağılımı","skills":["Okuma","İşyeri dili"],"goal":"Uzun bir toplantı tutanağında karar, itiraz, sorumluluk ve son tarihleri beş soruda izlemek.","explanation":"Tutanaklarda konuşmacıların rolleri, kimin neyi savunduğu ve sonunda neyin kararlaştırıldığı ayrılmalıdır. “schlägt vor”, “wendet ein”, “bittet um Umsetzung”, “bis 30.6.” gibi işaretler önemlidir. Bir kişinin görüşü ile şirketin nihai kararını birbirine karıştırma.","examples":[["Die Geschäftsführung bittet Vertrieb und Produktion um einen gemeinsamen Lösungsvorschlag.","Yönetim satış ve üretimden ortak çözüm önerisi istiyor.","Nihai görev."],["Die Produktionsleitung weist auf fehlende Kapazitäten hin.","Üretim yönetimi kapasite eksikliğine dikkat çekiyor.","İtiraz/gerekçe."]],"quiz":[{"q":"Toplantı tutanağında “wer macht was bis wann?” sorusunu çözmek için neye bakılır?","o":["Sadece ilk paragrafa","Sorumlu kişi, eylem fiili ve tarih notlarına","Yalnızca başlığa"],"a":1,"why":"Görev dağılımı kişi + eylem + zaman üçlüsüyle izlenir."},{"q":"Bu bölüm kaç çoktan seçmeli item içerir?","o":["4","5","7"],"a":1,"why":"Lesen Teil 4 beş MC itemden oluşur."}]},{"id":20,"unit":"DTB C1 entegre görevler","title":"Lesen und Schreiben: şikâyete profesyonel yanıt","skills":["Okuma","Yazma","Mediation"],"goal":"Bir e-posta zincirini doğru anlayıp ekip liderinin tüm talimatlarını müşteriye uygun kayıtla aktarmak.","explanation":"Bu görevde önce iki okuma sorusu çözülür, sonra müşteri e-postasına yanıt yazılır. Yazıda iç yazışmanın öfkeli veya kaba ifadeleri kopyalanmamalı; bilgi profesyonel biçimde yeniden formüle edilmelidir. Amaç “kim haklı?” tartışması değil, şikâyeti kabul etmek, durumu açıklamak, çözüm adımlarını netleştirmek ve uygun tonu korumaktır.","examples":[["Wir bedauern, dass es bei der Lieferung zu Schwierigkeiten gekommen ist.","Teslimatta sorun yaşandığı için üzgünüz.","Profesyonel açılış."],["Wir prüfen den Vorgang umgehend und melden uns spätestens morgen mit einem konkreten Lösungsvorschlag.","Konuyu hemen inceleyip en geç yarın somut çözümle döneceğiz.","Net eylem ve süre."]],"quiz":[{"q":"İç talimatta “Das ist eine Unverschämtheit!” yazıyorsa müşteriye ne yapmalısın?","o":["Aynen aktarmak","Nötr ve çözüm odaklı biçimde yeniden ifade etmek","Hiç cevap vermemek"],"a":1,"why":"Mediation görevinde içeriği hedef kişiye ve duruma uygun biçimde aktarmak gerekir."},{"q":"Lesen und Schreiben bloğu için toplam süre nedir?","o":["10 dakika","20 dakika","45 dakika"],"a":1,"why":"Bu entegre blok 20 dakikadır."}]},{"id":21,"unit":"DTB C1 dinleme","title":"Hören Teil 1: iş akışı, sorun ve öneri","skills":["Dinleme","Ayrıntı"],"goal":"Üç işyeri konuşmasında ana durumu ve bir ayrıntıyı toplam altı itemle yakalamak.","explanation":"Her konuşma yalnızca bir kez dinlenir. Her konuşma için bir doğru/yanlış ve bir çoktan seçmeli soru vardır. Dinlemeden önce seçeneklerdeki farkı gör: “geçici çözüm”, “kalıcı personel değişikliği”, “dış danışman” gibi seçenekler hangi ayrıntının beklendiğini gösterir.","examples":[["Wir brauchen zunächst eine Übergangslösung für die nächsten zwei Wochen.","Önce önümüzdeki iki hafta için geçici çözüm lazım.","Zaman sınırı ana ipucu."],["Langfristig sollten wir den Ablauf dokumentieren.","Uzun vadede süreci belgelemeliyiz.","Kısa ve uzun vadeyi ayır."]],"quiz":[{"q":"Hören Teil 1’de konuşmalar kaç kez dinlenir?","o":["1","2","3"],"a":0,"why":"Konuşmalar bir kez dinlenir."},{"q":"Üç konuşmada toplam kaç item vardır?","o":["3","6","9"],"a":1,"why":"Her konuşmaya iki item düşer: toplam 6."}]},{"id":22,"unit":"DTB C1 dinleme","title":"Hören Teil 2: argümantasyonu eşleştirme","skills":["Dinleme","Argümantasyon"],"goal":"Dört kısa konuşmada konuşmacının temel argümanını altı ifadeden doğru olanla eşleştirmek.","explanation":"Kelime eşleşmesine değil, konuşmacının sonuç cümlesine odaklan. Bir kişi “Abteilung wechseln” kelimesini kullanabilir ama bunu eleştiriyor olabilir. “deshalb”, “entscheidend ist”, “ich halte ... für” gibi tutum göstergeleri ana argümanı verir.","examples":[["Entscheidend ist nicht die neue Struktur, sondern die klare Zuständigkeit.","Belirleyici olan yeni yapı değil, açık sorumluluktur.","Ana tez."],["Ein Wechsel kann sinnvoll sein, wenn dadurch neue Entwicklungsmöglichkeiten entstehen.","Değişim yeni gelişim fırsatı yaratıyorsa anlamlı olabilir.","Koşullu görüş."]],"quiz":[{"q":"Bu görevde en önemli bilgi hangisidir?","o":["Konuşmacının kullandığı tek tek anahtar kelimeler","Konuşmacının vardığı ana sonuç / tutum","Konuşmanın ilk kelimesi"],"a":1,"why":"Seçenekler argümantasyonun ana fikrini parafraz eder."},{"q":"Kaç konuşma eşleştirilir?","o":["3","4","5"],"a":1,"why":"Hören Teil 2 dört konuşma içerir."}]},{"id":23,"unit":"DTB C1 dinleme","title":"Hören Teil 3: şirket sunumunu izleme","skills":["Dinleme","Sunum"],"goal":"Bir işyeri sunumunda dört bilgi alanını takip edip dört MC soruyu çözmek.","explanation":"Sunum genellikle bölümler halinde ilerler: satış, mali durum, personel, proje durumu gibi. Soruları önceden okuyup her soru için beklenen bilgi türünü belirle. Sunum bir kez oynar; notlarda cümle değil, sayı, yön (artış/azalış), neden ve sonuç yaz.","examples":[["Der Umsatz ist gestiegen, obwohl der Absatz im ersten Quartal stagnierte.","İlk çeyrekte satış adedi durağan olsa da ciro arttı.","İki göstergeyi karıştırma."],["Für das zweite Halbjahr sind keine Stellenstreichungen geplant.","İkinci yarı için işten çıkarma planlanmıyor.","Negatif bilgi önemli."]],"quiz":[{"q":"Sunum dinlerken en verimli not biçimi hangisidir?","o":["Tam cümleler yazmak","Sayı + eğilim + neden gibi kısa işaretler","Hiç not almamak"],"a":1,"why":"Tek dinlemede kısa işaretler ana bilgiyi kaçırmadan kaydetmeyi sağlar."},{"q":"Hören Teil 3 kaç MC item içerir?","o":["4","5","6"],"a":0,"why":"Dört soru vardır."}]},{"id":24,"unit":"DTB C1 dinleme","title":"Hören Teil 4: telefon mesajlarında talep ve eylem","skills":["Dinleme","İşyeri dili"],"goal":"Beş kısa telefon mesajında arayanın amacı ve beklediği eylemi tek dinlemede anlamak.","explanation":"Telefon mesajlarında isim, zaman, değişiklik, talep ve “kim ne yapmalı?” bilgisi hızlı gelir. Fiillere odaklan: “verschieben”, “bestätigen”, “zurückrufen”, “einspringen”, “weiterleiten”. Seçeneklerde özne değişmişse anlam tamamen değişebilir.","examples":[["Könnten Sie den Termin bitte auf Donnerstag verschieben?","Randevuyu perşembeye alabilir misiniz?","Eylem talebi."],["Bitte rufen Sie mich bis 15 Uhr zurück.","Lütfen saat 15’e kadar beni geri arayın.","Son tarih."]],"quiz":[{"q":"Telefon mesajında en kritik üç unsur hangisidir?","o":["Renk, yaş, hava","Kim arıyor, neden arıyor, ne yapılmalı","Sadece telefon numarası"],"a":1,"why":"Görev iletişim amacı ve eylemi yakalamayı ölçer."},{"q":"Her telefon mesajı kaç kez dinlenir?","o":["Bir kez","İki kez","Üç kez"],"a":0,"why":"Hören Teil 4’te her mesaj bir kez dinlenir."}]},{"id":25,"unit":"DTB C1 entegre görevler","title":"Hören und Schreiben: telefon notu ve bilgi aktarımı","skills":["Dinleme","Yazma","Mediation"],"goal":"Tek dinlemede arama nedenini seçip ad, iletişim bilgisi, önemli ayrıntılar ve yapılacak işi doğru aktarmak.","explanation":"Bu 5 dakikalık görev kısa ama çok yoğundur. Önce arama nedenini seçersin, sonra telefon notunda adı, iletişim bilgisini, önemli ayrıntıları ve “zu erledigen” alanını doldurursun. Amaç kelimesi kelimesine dikte değil; iş arkadaşının doğru eylemi yapmasını sağlayacak bilgiyi eksiksiz aktarmaktır.","examples":[["Frau Neumann bittet um Rückruf wegen einer geänderten Lieferadresse.","Bayan Neumann değişen teslimat adresi nedeniyle geri arama istiyor.","Arama nedeni + eylem."],["Zu erledigen: neue Adresse im Auftrag prüfen und Kundin zurückrufen.","Yapılacak: siparişte yeni adresi kontrol et ve müşteriyi ara.","İşlevsel telefon notu."]],"quiz":[{"q":"Telefon notunda “zu erledigen” alanı neyi göstermelidir?","o":["Arayanın tüm konuşmasını","Meslektaşın yapması gereken somut eylemi","Sadece selamlaşmayı"],"a":1,"why":"Bu alan eylem transferini ölçer."},{"q":"Hören und Schreiben için kaç dakika vardır?","o":["5","15","20"],"a":0,"why":"Bu blok 5 dakikadır."}]},{"id":26,"unit":"DTB C1 dil yapıları","title":"Sprachbausteine Teil 1: iş e-postasında kelime seçimi","skills":["Dilbilgisi","Kelime","Yazma"],"goal":"Bir iş e-postasındaki altı boşluğu on aday kelime/ifade arasından bağlama ve rektiona göre tamamlamak.","explanation":"Bu bölümde her kelime yalnızca bir kez kullanılabilir ve bazı adaylar fazladır. Bağlam, sabit eşdizim ve rektion birlikte kontrol edilir: “auf eine Frist verzichten”, “unter welchen Bedingungen”, “einen Termin vereinbaren”. Türkçe çeviri tek başına yeterli değildir.","examples":[["auf die Einhaltung der Frist verzichten","süreye uyma şartından vazgeçmek","Rektion: auf + Akk."],["unter welchen Bedingungen","hangi koşullar altında","Sabit ifade."]],"quiz":[{"q":"Doğru eşdizim hangisidir?","o":["auf die Frist verzichten","von die Frist verzichten","mit die Frist verzichten"],"a":0,"why":"verzichten auf + Akkusativ."},{"q":"Bu bölüm kaç boşluk içerir?","o":["6","10","12"],"a":0,"why":"6 boşluk ve 10 aday vardır."}]},{"id":27,"unit":"DTB C1 dil yapıları","title":"Sprachbausteine Teil 2: deyimsel ve yapısal seçenekler","skills":["Dilbilgisi","Üslup"],"goal":"Altı boşlukta üç seçenek arasından doğal, resmî ve dilbilgisel olarak doğru ifadeyi seçmek.","explanation":"Bu bölüm C1’de “gramer mi kelime mi?” ayrımının yapay olduğunu gösterir. “wie befürchtet”, “in Kauf nehmen”, “aus meiner Sicht”, “ob sich das umsetzen lässt” gibi kalıplar hem yapı hem kullanım bilgisini ölçer. Cümleyi sadece boşluğa kadar değil, tamamını oku.","examples":[["Wie befürchtet verzögert sich die Lieferung.","Korkulduğu gibi teslimat gecikiyor.","Doğal kalıp."],["Den zusätzlichen Aufwand müssen wir in Kauf nehmen.","Ek çabayı göze almalıyız.","Funktionsverbgefüge."]],"quiz":[{"q":"Doğru ifade hangisidir?","o":["aus meiner Sicht","auf meiner Sicht","bei meiner Sicht"],"a":0,"why":"Standart ifade “aus meiner Sicht”tir."},{"q":"“etwas in Kauf nehmen” ne anlama gelir?","o":["bir şeyi tamamen reddetmek","olumsuz bir sonucu göze almak/kabullenmek","bir şeyi satın almak"],"a":1,"why":"Soyut kullanımda istenmeyen sonucu kabul etmek demektir."}]},{"id":28,"unit":"DTB C1 yazma","title":"Schreiben: yönetime gerekçeli Stellungnahme","skills":["Yazma","Argümantasyon"],"goal":"İki konudan birini seçip artı-eksi, örnek, kişisel görüş ve sonuç içeren profesyonel bir Stellungnahme yazmak.","explanation":"Görev işyeri bağlamında yönetimin senden yazılı görüş istemesi şeklindedir. Sadece “pro/contra” listelemek yetmez; nedenleri ağırlıklandırmalı, örneklerle desteklemeli, kendi pozisyonunu açıkça belirtmeli ve sonuç çıkarmalısın. Değerlendirmede görev yerine getirme, iletişimsel yapı, biçimsel doğruluk ve dilsel araçların genişliği önemlidir.","examples":[["Für die Maßnahme spricht vor allem, dass …","Önlem lehine en önemli nokta …","Argüman açma."],["Unter Abwägung der genannten Aspekte halte ich … für die sinnvollste Lösung.","Yukarıdaki unsurları tartınca … en mantıklı çözüm görüyorum.","Sonuç ve pozisyon."]],"quiz":[{"q":"Stellungnahme’de hangisi zorunlu işlevlerden biridir?","o":["Sadece kişisel hikâye anlatmak","Avantaj/dezavantajları tartıp kendi pozisyonunu ve sonucu vermek","Yalnızca madde işareti kullanmak"],"a":1,"why":"Görev açıkça Vor-/Nachteile, örnek, kendi görüşü ve Fazit ister."},{"q":"DTB yazmada global dil değerlendirmesi hangi alanları içerir?","o":["Sadece yazım","İletişimsel yapı, biçimsel doğruluk, dilsel araçların genişliği","Sadece kelime sayısı"],"a":1,"why":"Resmî kriter II–IV bu üç alanı kapsar."}]},{"id":29,"unit":"DTB C1 konuşma","title":"Sprechen Teil 1A–1C: spontan monolog, sorular ve yeniden anlatım","skills":["Konuşma","Mediation","Akıcılık"],"goal":"Hazırlıksız yaklaşık iki dakikalık bir konuşma yapmak, sınav görevlisinin sorularını yanıtlamak ve partnerin söylediklerinden bir yönü kendi sözlerinle açıklamak.","explanation":"Sözlü sınavda hazırlık süresi yoktur. Teil 1A’da iki konudan birini seçip yaklaşık iki dakika konuşursun. Teil 1B’de sınav görevlisinin derinleştirici sorularını spontan yanıtlamalısın. Teil 1C’de partner, senin yanıtlarından bir yönü kendi sözleriyle açıklar; sonra roller değişir. Ezberlenmiş metin yerine doğal yapılandırma gerekir.","examples":[["Ich möchte zunächst erläutern, warum das Thema im Arbeitsalltag relevant ist.","Önce konunun iş hayatında neden önemli olduğunu açıklamak istiyorum.","Spontan yapı kurma."],["Wenn ich meinen Kollegen richtig verstanden habe, geht es vor allem darum, dass …","Meslektaşımı doğru anladıysam asıl mesele …","Partner bilgisini yeniden ifade etme."]],"quiz":[{"q":"Teil 1A’da yaklaşık ne kadar konuşulur?","o":["30 saniye","2 dakika","5 dakika"],"a":1,"why":"Her katılımcı yaklaşık iki dakika konuşur; ardından sorular gelir."},{"q":"Teil 1C’nin temel becerisi nedir?","o":["Metni ezberden okumak","Partnerin bir noktasını kendi sözleriyle açıklamak","Sadece evet/hayır demek"],"a":1,"why":"Bu bölüm dinleme + yeniden ifade etme / Mediation içerir."}]},{"id":30,"unit":"DTB C1 konuşma ve sınav hazırlığı","title":"Sprechen Teil 2–3: işyeri small talk, sorun çözme ve geçme stratejisi","skills":["Konuşma","Etkileşim","Strateji"],"goal":"Doğal meslektaş konuşması yürütmek, işyeri sorununa çözüm üretmek, görev paylaşmak ve sınav sonucunu doğru yorumlamak.","explanation":"Teil 2’de çalışma saatleri, işe gidiş, boş zaman, spor veya çocuk bakımı gibi konularda yaklaşık üç dakikalık doğal bir meslektaş sohbeti yürütülür. Teil 3’te somut bir işyeri sorununa çözüm bulunur: kısa ve uzun vadeli seçenekler, sorumluluklar ve sonraki adımlar konuşulur. Sınavı geçmek için toplam 240 puanın en az 144’ü gerekir; ayrıca dört becerinin en az üçünde 36/60 veya üzeri olmalı, telafi edilen tek beceri ise 24–36 aralığında kalmalıdır.","examples":[["Dann übernehme ich die Rückmeldung an den Kunden, und du klärst parallel die Lieferung mit dem Lager.","O zaman müşteriye dönüşü ben yapayım, sen de paralel olarak depoyla teslimatı netleştir.","Görev paylaşımı."],["Langfristig sollten wir den Ablauf dokumentieren, damit derselbe Fehler nicht wieder auftritt.","Uzun vadede aynı hatanın tekrarlanmaması için süreci belgelemeliyiz.","Kalıcı iyileştirme."]],"quiz":[{"q":"Teil 3’te yalnızca bir çözüm söylemek yeterli mi?","o":["Evet","Hayır; seçenekleri tartışıp ne yapılacağını ve kimin yapacağını netleştirmek gerekir","Sadece partner konuşur"],"a":1,"why":"Görev ortak çözüm, uzun vadeli iyileştirme ve görev paylaşımı bekler."},{"q":"Genel geçme kuralında toplam en az kaç puan gerekir?","o":["120","144","180"],"a":1,"why":"240 toplam puanın %60’ı = 144 puan."}]}],"grammarSets":[{"id":"passiv","title":"Edilgen yapı (Passiv)","subtitle":"Süreç, durum ve öznesiz edilgen yapı","questions":[{"q":"Die Kommission ___ den Antrag gestern ___.","o":["hat / abgelehnt","ist / abgelehnt worden","wurde / abgelehnt worden","war / ablehnen"],"a":1,"why":"Perfekt Vorgangspassiv: ist + Partizip II + worden."},{"q":"Aktiv: Man diskutiert über die Folgen. Doğru Passiv?","o":["Die Folgen werden diskutiert über.","Über die Folgen wird diskutiert.","Über die Folgen werden diskutiert.","Es diskutiert über die Folgen."],"a":1,"why":"Akkusativ nesnesi olmadığı için öznesiz pasif; fiil tekil."},{"q":"“Die Tür ist geschlossen.” neyi vurgular?","o":["Kapanma sürecini","Ortaya çıkmış durumu","Failin kim olduğunu","Geleceği"],"a":1,"why":"sein + Partizip II = Zustandspassiv."},{"q":"Das Gebäude wurde ___ ein Erdbeben beschädigt.","o":["von","durch","mit","bei"],"a":1,"why":"Nedensel/araçsal etken için “durch + Akk.” uygundur."},{"q":"Welche Form ist korrekt?","o":["Die Daten sind geprüft geworden.","Die Daten sind geprüft worden.","Die Daten haben geprüft worden.","Die Daten wurden geprüft gewesen."],"a":1,"why":"Perfekt Passiv’te “worden” kullanılır."},{"q":"Niemand hat eine Lösung gefunden. →","o":["Keine Lösung ist gefunden.","Es wurde keine Lösung gefunden.","Keine Lösung wurde finden.","Niemand wurde eine Lösung gefunden."],"a":1,"why":"Niemand çoğu zaman pasifte olumsuzlukla ifade edilir."},{"q":"Der Antrag ___ bereits genehmigt; wir warten nur auf die Zustellung.","o":["wird","ist","wurde gerade","würde"],"a":1,"why":"Burada sonuç durumu vurgulanıyor."},{"q":"Man half den Betroffenen sofort. →","o":["Die Betroffenen wurden sofort geholfen.","Den Betroffenen wurde sofort geholfen.","Den Betroffenen wurden sofort geholfen.","Es wurden die Betroffenen geholfen."],"a":1,"why":"helfen Dativ alır; öznesiz pasif tekil “wurde”."}]},{"id":"nvv","title":"İsim-fiil birleşimleri","subtitle":"Nomen-Verb-Verbindungen ve işlevsel fiil yapıları","questions":[{"q":"eine Entscheidung ___","o":["machen","treffen","tun","setzen"],"a":1,"why":"Standart eşdizim: eine Entscheidung treffen."},{"q":"Kritik ___ an der Reform","o":["üben","machen","stellen","geben"],"a":0,"why":"Kritik an etwas üben."},{"q":"etwas in Erwägung ___","o":["bringen","ziehen","nehmen","führen"],"a":1,"why":"in Erwägung ziehen = değerlendirmek."},{"q":"zur Verfügung ___","o":["sein/stehen","machen","ziehen","setzen"],"a":0,"why":"zur Verfügung stehen / stellen."},{"q":"in Kraft ___","o":["kommen","treten","gehen","laufen"],"a":1,"why":"in Kraft treten = yürürlüğe girmek."},{"q":"Maßnahmen ___","o":["ergreifen","nehmen","leisten","stellen"],"a":0,"why":"Maßnahmen ergreifen = önlem almak."},{"q":"eine Frage zur Sprache ___","o":["bringen","ziehen","treffen","halten"],"a":0,"why":"zur Sprache bringen = gündeme getirmek."},{"q":"einen Beitrag zu etwas ___","o":["leisten","machen","setzen","führen"],"a":0,"why":"einen Beitrag leisten."}]},{"id":"modal_obj","title":"Kip fiilleri – nesnel kullanım","subtitle":"Modalverben: zorunluluk, izin, olasılık ve niyet","questions":[{"q":"Du ___ hier nicht parken. Es ist verboten.","o":["musst","darfst","kannst","sollst"],"a":1,"why":"nicht dürfen = yasak."},{"q":"Wir ___ die Frist nicht einhalten; es war unmöglich.","o":["durften","konnten","sollten","wollten"],"a":1,"why":"nicht können = olanaksız/yetersiz olmak."},{"q":"Es ist nicht notwendig, dass du kommst. → Du ___ kommen.","o":["darfst nicht","musst nicht","sollst nicht","willst nicht"],"a":1,"why":"nicht müssen = zorunda olmamak."},{"q":"Perfekt: Wir ___ früher abreisen ___.","o":["haben / müssen","sind / gemusst","haben / gemusst","wurden / müssen"],"a":0,"why":"Ersatzinfinitiv: haben + Infinitiv + Modalinfinitiv."},{"q":"Man erwartet von uns, dass wir den Bericht überarbeiten. → Wir ___ den Bericht überarbeiten.","o":["sollen","dürfen","mögen","können"],"a":0,"why":"sollen görev/beklenti aktarır."},{"q":"Er weigert sich zu unterschreiben. → Er ___ nicht unterschreiben.","o":["will","darf","kann","muss"],"a":0,"why":"nicht wollen = isteksizlik/ret."},{"q":"Die Genehmigung erlaubt uns die Nutzung. → Wir ___ das Gebäude nutzen.","o":["dürfen","müssen","sollen","wollen"],"a":0,"why":"dürfen = izin."},{"q":"Sie ist fähig, komplexe Daten zu analysieren. → Sie ___ komplexe Daten analysieren.","o":["soll","kann","darf","muss"],"a":1,"why":"können = yetenek."}]},{"id":"modal_subj","title":"Kip fiilleri – öznel kullanım","subtitle":"Modalverben: tahmin, çıkarım, söylenti ve mesafe","questions":[{"q":"Er ___ schon angekommen sein; sein Auto steht draußen. (çok güçlü çıkarım)","o":["könnte","muss","soll","will"],"a":1,"why":"subjektives müssen = güçlü çıkarım."},{"q":"Die Preise ___ nächstes Jahr leicht sinken. (olasılık)","o":["könnten","müssen","wollen","sollen"],"a":0,"why":"könnte = belirsiz olasılık."},{"q":"Die Ministerin ___ bereits informiert gewesen sein. (duyuma göre)","o":["muss","soll","will","darf"],"a":1,"why":"sollen = ikinci el/doğrulanmamış bilgi."},{"q":"Der Zeuge ___ alles gesehen haben. (kendisi iddia ediyor, konuşan mesafeli)","o":["will","muss","darf","soll"],"a":0,"why":"wollen subjektiv = kişinin kendi iddiası, konuşan şüpheci olabilir."},{"q":"Die Ursache ___ in der neuen Software liegen. (muhtemelen)","o":["dürfte","soll","will","muss immer"],"a":0,"why":"dürfte = yüksek olasılık/varsayım."},{"q":"Das ___ kein Zufall sein. (güçlü olumsuz çıkarım)","o":["kann","muss","soll","darf"],"a":0,"why":"“Das kann kein … sein” = kesinlikle olamaz."},{"q":"Vergangenheit: Vielleicht hat er den Termin vergessen. → Er ___ den Termin vergessen haben.","o":["könnte","soll","will","muss"],"a":0,"why":"könnte + Infinitiv Perfekt."},{"q":"Rat: Du ___ deine Argumente klarer strukturieren.","o":["solltest","willst","darfst","kannst nur"],"a":0,"why":"Konjunktiv II von sollen = tavsiye."}]},{"id":"k2","title":"Dilek/varsayım kipi (Konjunktiv II)","subtitle":"Konjunktiv II ile gerçek dışılık, ihtiyat ve tavsiye","questions":[{"q":"___ mehr Daten vorhanden, ließe sich die Hypothese besser prüfen.","o":["Wären","Sind","Seien","Wurden"],"a":0,"why":"İrreal koşul: Wären …, ließe …"},{"q":"Geçmiş pişmanlık: Wir ___ früher reagieren ___.","o":["hätten / sollen","würden / sollen","seien / sollen","haben / sollen"],"a":0,"why":"hätten + Infinitiv + sollen."},{"q":"Temkinli öneri hangisidir?","o":["Das ist so.","Es wäre denkbar, dass …","Das muss so sein.","Mach das!"],"a":1,"why":"Konjunktiv II iddiayı yumuşatır."},{"q":"Wenn ich mehr Zeit ___, ___ ich den Bericht überarbeiten.","o":["hätte / würde","habe / werde","sei / würde","hatte / würde"],"a":0,"why":"İrreal şart."},{"q":"Es ___ sinnvoll, die Stichprobe zu vergrößern.","o":["wäre","sei","wird","war immer"],"a":0,"why":"Temkinli değerlendirme."},{"q":"Er tut so, als ___ er alles.","o":["wüsste","weiß","wisse","wusste immer"],"a":0,"why":"als ob/als + Konjunktiv II irreal karşılaştırma."},{"q":"Das ___ ich an deiner Stelle vermeiden.","o":["würde","werde","sei","habe"],"a":0,"why":"Tavsiye için Konjunktiv II."},{"q":"Hätten wir die Warnung ernst genommen, ___ es nicht so weit gekommen.","o":["wäre","ist","sei","würde jetzt"],"a":0,"why":"Geçmiş irreal koşul: wäre … gekommen."}]},{"id":"k1","title":"Dolaylı anlatım kipi (Konjunktiv I)","subtitle":"Konjunktiv I ile dolaylı anlatım ve kaynak mesafesi","questions":[{"q":"Die Autorin sagt, die Daten ___ eindeutig.","o":["seien","sind","wären nur","werden gewesen"],"a":0,"why":"Konjunktiv I plural: seien."},{"q":"Er erklärt, er ___ keine Kenntnis davon.","o":["habe","hat","hätte immer","haben"],"a":0,"why":"Konjunktiv I: habe."},{"q":"Der Sprecher behauptet, die Maßnahme ___ Wirkung.","o":["zeige","zeigt","zeigte zwingend","würde gezeigt"],"a":0,"why":"Konjunktiv I: zeige."},{"q":"Indikativ ve Konjunktiv I çakışırsa sık kullanılan çözüm?","o":["Konjunktiv II","Imperativ","Passiv zorunlu","Futur II"],"a":0,"why":"Mesafeyi görünür kılmak için Ersatzkonjunktiv II."},{"q":"Sie sagten, sie ___ nichts bemerkt.","o":["hätten","haben","seien bemerken","würden bemerkt"],"a":0,"why":"Plural biçimde Konjunktiv I “haben” ile çakıştığı için “hätten”."},{"q":"Konjunktiv I’in temel amacı?","o":["Kaynağı mesafeli aktarmak","Geleceği kesinleştirmek","Emir vermek","Soru sormak"],"a":0,"why":"Özellikle haber/rapor dilinde aktarım işlevi."},{"q":"Die Expertin betont, man ___ die Daten vorsichtig interpretieren.","o":["müsse","muss","musste","würde müssen gewesen"],"a":0,"why":"Konjunktiv I von müssen: müsse."},{"q":"Er meint, das Ergebnis ___ überraschend.","o":["sei","ist","wäre nur vielleicht","war"],"a":0,"why":"Konjunktiv I von sein: sei."}]},{"id":"nom","title":"Adlaştırma / fiilleştirme","subtitle":"Nominalisierung / Verbalisierung: yoğun akademik yapı ↔ açık fiil cümlesi","questions":[{"q":"“wegen der steigenden Kosten” →","o":["weil die Kosten steigen","obwohl die Kosten steigen","damit die Kosten steigen","wenn die Kosten nicht steigen"],"a":0,"why":"wegen = neden."},{"q":"“trotz der Kritik” →","o":["obwohl es Kritik gibt","weil es Kritik gibt","damit es Kritik gibt","bevor es Kritik gibt"],"a":0,"why":"trotz = taviz, obwohl."},{"q":"“nach Abschluss der Studie” →","o":["nachdem die Studie abgeschlossen worden war","weil die Studie beginnt","bevor man die Studie abschließt","falls die Studie endet"],"a":0,"why":"nach = zaman ilişkisi, nachdem."},{"q":"“zur Verbesserung der Qualität” →","o":["damit die Qualität verbessert wird","weil die Qualität schlecht ist","obwohl die Qualität steigt","nachdem die Qualität sank"],"a":0,"why":"zur + nominal amaç = damit/um … zu."},{"q":"“bei einer weiteren Verschärfung” →","o":["wenn sich die Lage weiter verschärft","obwohl die Lage besser wird","weil niemand reagiert","nachdem alles vorbei ist"],"a":0,"why":"bei + durum çoğu kez wenn/falls."},{"q":"“aufgrund fehlender Daten” →","o":["weil Daten fehlen","obwohl Daten fehlen","damit Daten fehlen","bevor Daten fehlen"],"a":0,"why":"aufgrund = neden."},{"q":"“während der Auswertung” →","o":["während die Daten ausgewertet werden","weil die Daten fehlen","nachdem alles fertig ist","damit man beginnt"],"a":0,"why":"Eş zamanlılık."},{"q":"Nominal yapı ne zaman özellikle uygundur?","o":["Bilgiyi yoğun ve resmî biçimde paketlemek gerektiğinde","Her konuşma cümlesinde","Sadece A1 düzeyinde","Sadece sorularda"],"a":0,"why":"Akademik/resmî registerda yoğunluk sağlar."}]},{"id":"cohesion","title":"Bağlaşıklık ve bağlaçlar","subtitle":"C1 düzeyinde metin ilişkileri","questions":[{"q":"Taviz: ___ die Stichprobe klein ist, sind die Ergebnisse relevant.","o":["Wenngleich","Folglich","Dadurch","Zumal"],"a":0,"why":"Wenngleich = her ne kadar."},{"q":"Sonuç: Die Nachfrage sank. ___ wurde das Angebot reduziert.","o":["Folglich","Wenngleich","Indem","Während"],"a":0,"why":"Folglich = bunun sonucunda."},{"q":"Karşılaştırmalı karşıtlık: Gruppe A profitiert. ___ entstehen Gruppe B Nachteile.","o":["Demgegenüber","Infolgedessen","Daher","Somit"],"a":0,"why":"Demgegenüber iki grubu karşı karşıya getirir."},{"q":"Koşul: Die Regel gilt, ___ keine Ausnahme genehmigt wird.","o":["sofern","obwohl","zumal","wodurch"],"a":0,"why":"sofern = şu koşulla ki/eğer."},{"q":"Ek gerekçe: Die Maßnahme ist teuer, ___ ihr Nutzen unklar ist.","o":["zumal","folglich","hingegen","indem"],"a":0,"why":"zumal ek/kuvvetlendirici gerekçe verir."},{"q":"Araç/yöntem: Man senkt Kosten, ___ man Prozesse automatisiert.","o":["indem","obwohl","sofern","während dagegen"],"a":0,"why":"indem = nasıl/yöntem."},{"q":"Gönderim: Es wurden zwei Modelle getestet. ___ erwies sich als robuster.","o":["Letzteres","Folglich","Wenngleich","Daher dass"],"a":0,"why":"Letzteres ikinci modele gider."},{"q":"“Nichtsdestotrotz” hangi ilişkiyi verir?","o":["Taviz/karşıtlık","Amaç","Zaman","Koşul"],"a":0,"why":"Beklenen sonuca rağmen karşıt durum."}]}],"styleSets":[{"id":"register","title":"Kayıt ve üslup","questions":[{"q":"Yarı resmî e-posta için en uygun ifade?","o":["Das ist echt Mist.","Ich möchte Sie auf eine Unstimmigkeit aufmerksam machen.","Ey, könnt ihr das fixen?","Mega nervig."],"a":1,"why":"Nazik, açık ve profesyonel kayıt."},{"q":"Akademik temkinli ifade?","o":["Das beweist hundertprozentig …","Die Befunde legen nahe, dass …","Jeder weiß, dass …","Ganz klar …"],"a":1,"why":"“legen nahe” kanıt derecesini uygun tutar."},{"q":"Tartışmada kibar itiraz?","o":["Unsinn.","Ich sehe den Punkt, allerdings …","Falsch!","Quatsch."],"a":1,"why":"Partneradäquat ve etkileşimli."},{"q":"Resmî öneri?","o":["Mach doch einfach …","Als mögliche Lösung schlage ich vor, …","Du musst halt …","Easy: …"],"a":1,"why":"Uygun register."},{"q":"Nötr görüş belirtme?","o":["Meines Erachtens …","Ich schwöre …","Voll krass …","Safe …"],"a":0,"why":"Nötr/resmî argümantasyon."},{"q":"Resmî talep?","o":["Wäre es möglich, …?","Gib mir …","Los, mach …","Kannste …?"],"a":0,"why":"Nazik ve uygun."},{"q":"Akademik sınırlama?","o":["Dies gilt allerdings nur unter der Voraussetzung, dass …","Das gilt immer.","Keine Ahnung, aber …","Ist halt so."],"a":0,"why":"Koşulu açıklar."},{"q":"Sunum geçişi?","o":["Jetzt mal egal.","Damit komme ich zum zweiten Aspekt.","Whatever.","Und so."],"a":1,"why":"Dinleyiciye yapı sinyali verir."}]},{"id":"paraphrase","title":"Parafraz","questions":[{"q":"“berücksichtigen” ≈","o":["in Betracht ziehen","verwerfen","bestreiten","verschweigen"],"a":0,"why":"İkisi de değerlendirmeye katmak."},{"q":"“auf etwas zurückzuführen sein” ≈","o":["durch etwas bedingt sein","etwas verhindern","etwas verbergen","etwas beschleunigen"],"a":0,"why":"Nedeni belirtir."},{"q":"“von großer Bedeutung” ≈","o":["maßgeblich","belanglos","zufällig","überflüssig"],"a":0,"why":"maßgeblich = önemli/belirleyici."},{"q":"“etwas außer Acht lassen” ≈","o":["etwas ignorieren","etwas fördern","etwas belegen","etwas erweitern"],"a":0,"why":"Göz ardı etmek."},{"q":"“einen Einwand erheben” ≈","o":["widersprechen","zustimmen","abschließen","zusammenfassen"],"a":0,"why":"İtiraz etmek."},{"q":"“sich als tragfähig erweisen” ≈","o":["funktionieren / belastbar sein","scheitern","verboten sein","unverständlich sein"],"a":0,"why":"Uygulanabilir/sağlam çıkmak."},{"q":"“die These untermauern” ≈","o":["die These stützen","die These vergessen","die These vermeiden","die These abschwächen"],"a":0,"why":"Kanıt/argümanla desteklemek."},{"q":"“eine Entwicklung zeichnet sich ab” ≈","o":["eine Entwicklung wird erkennbar","alles bleibt gleich","etwas wird verboten","etwas endet sofort"],"a":0,"why":"Bir eğilim görünür hale gelir."}]},{"id":"collocations","title":"C1 eşdizimler","questions":[{"q":"eine Schlussfolgerung ___","o":["ziehen","machen","bauen","stellen"],"a":0,"why":"eine Schlussfolgerung ziehen."},{"q":"eine Maßnahme ___","o":["ergreifen","schreiben","legen","laufen"],"a":0,"why":"Maßnahmen ergreifen."},{"q":"zur Debatte ___","o":["stehen","laufen","ziehen","fallen immer"],"a":0,"why":"zur Debatte stehen."},{"q":"einen Zusammenhang ___","o":["herstellen","kochen","setzen","laufen"],"a":0,"why":"einen Zusammenhang herstellen."},{"q":"eine Annahme ___","o":["in Frage stellen","ins Haus bringen","zu Fuß setzen","in Kraft machen"],"a":0,"why":"eine Annahme in Frage stellen."},{"q":"Verantwortung ___","o":["übernehmen","nehmen auf","machen","bauen"],"a":0,"why":"Verantwortung übernehmen."},{"q":"einen Antrag ___","o":["stellen","setzen","machen immer","ziehen"],"a":0,"why":"einen Antrag stellen."},{"q":"unter Druck ___","o":["geraten","kommen zu","ziehen","leisten"],"a":0,"why":"unter Druck geraten/stehen."}]},{"id":"nuance","title":"Nüans ve kanıt derecesi","questions":[{"q":"“legt nahe” hangi güçte?","o":["işaret ediyor / olası sonuç","kesin kanıtlıyor","reddediyor","yasaklıyor"],"a":0,"why":"Temkinli sonuç."},{"q":"“dürfte” (öznel) çoğu zaman?","o":["muhtemelen","kesinlikle","yasaktır","geçmiş emir"],"a":0,"why":"Yüksek olasılık/varsayım."},{"q":"“keineswegs” ne yapar?","o":["güçlü olumsuzlama","örnek verir","sonuç çıkarır","zaman gösterir"],"a":0,"why":"Kesinlikle değil."},{"q":"“durchaus” hangi nüansı taşıyabilir?","o":["beklenenden daha olumlu/onaylayıcı vurgu","tam ret","zaman","sayısal kesinlik"],"a":0,"why":"“gayet / durchaus” olumlu vurgu yapabilir."},{"q":"“nur bedingt” ne demektir?","o":["yalnızca sınırlı ölçüde","tamamen","kesinlikle","hiçbir koşulda"],"a":0,"why":"Koşullu/sınırlı geçerlilik."},{"q":"“weitgehend” ≈","o":["büyük ölçüde","hiç","tam olarak her zaman","rastgele"],"a":0,"why":"Tam değil ama büyük ölçüde."},{"q":"“kaum” ne ifade eder?","o":["çok az / neredeyse hiç","çok fazla","kesin","gereklilik"],"a":0,"why":"Düşük derece."},{"q":"“angeblich” ne sinyali verir?","o":["iddia edilen, doğrulanmamış bilgi","kesin kanıt","emir","izin"],"a":0,"why":"Kaynağa mesafe."}]}],"readingPractice":{"part1":{"title":"Bölüm 1 · Sözcük boşlukları","text":"Viele Städte testen sogenannte Superblocks. Dabei werden mehrere Straßen zu größeren Wohnbereichen zusammengefasst, in denen der Durchgangsverkehr stark begrenzt wird. Die Idee zielt ___(1)___, öffentlichen Raum neu zu verteilen. Flächen, die zuvor fast ausschließlich Autos ___(2)___, können für Bäume, Sitzplätze oder Spielbereiche genutzt werden. Kritiker weisen jedoch ___(3)___, dass Verkehr nicht einfach verschwindet, sondern sich verlagern kann. Deshalb kommt es ___(4)___ eine sorgfältige Planung an. Erste Auswertungen zeigen, dass die Akzeptanz steigt, wenn Anwohner frühzeitig ___(5)___ die Gestaltung einbezogen werden. Entscheidend ist außerdem, die Auswirkungen nicht nur kurzfristig, ___(6)___ über mehrere Jahre zu beobachten. So lässt sich prüfen, ob die Maßnahmen tatsächlich ___(7)___ einer besseren Luftqualität beitragen und ob benachbarte Straßen unverhältnismäßig ___(8)___ werden.","items":[{"o":["darauf ab","davon aus","dazu bei","damit ein"],"a":0},{"o":["zur Verfügung standen","in Anspruch nahmen","zugrunde lagen","in Kraft traten"],"a":1},{"o":["darauf hin","darüber aus","dazu bei","davon ab"],"a":0},{"o":["auf","an","um","für"],"a":1},{"o":["an","in","bei","zu"],"a":1},{"o":["aber auch","sondern","obwohl","währenddessen"],"a":1},{"o":["zu","bei","mit","an"],"a":0},{"o":["belastet","überzeugt","verfasst","erfasst"],"a":0}]},"part2":{"title":"Bölüm 2 · Yoğun bilgi içeren makale","text":"Immer mehr Unternehmen erproben eine Vier-Tage-Woche, doch hinter dem Begriff verbergen sich unterschiedliche Modelle. Manche reduzieren die Wochenarbeitszeit bei gleichem Lohn, andere verteilen die bisherige Arbeitszeit lediglich auf vier längere Tage. Für die Bewertung ist diese Unterscheidung entscheidend. Studien zu Pilotprojekten berichten häufig von höherer Zufriedenheit und weniger Fehltagen. Gleichzeitig warnen Forschende davor, aus kleinen, freiwillig teilnehmenden Stichproben allgemeine Schlüsse zu ziehen. Unternehmen, die sich für Pilotprojekte melden, sind oft bereits offen für flexible Arbeitsformen und verfügen über günstige organisatorische Voraussetzungen.\n\nEin zentrales Ergebnis vieler Versuche ist, dass die Produktivität nicht automatisch sinkt, wenn Arbeitszeit reduziert wird. Teams streichen etwa wenig wirksame Besprechungen, bündeln Kommunikationszeiten und automatisieren Routinen. Diese Verdichtung kann jedoch problematisch werden, wenn die gleiche Arbeitsmenge lediglich in weniger Zeit erledigt werden soll. Beschäftigte berichten dann zwar von einem zusätzlichen freien Tag, aber auch von stärkerem Zeitdruck an den übrigen Tagen. Besonders in Bereichen mit Schichtbetrieb oder direktem Kundenkontakt ist die Umsetzung kompliziert, weil Öffnungszeiten und Besetzung weiterhin gewährleistet werden müssen.\n\nAuch die langfristige Wirkung ist noch nicht abschließend geklärt. Während die Motivation zu Beginn eines Pilotprojekts häufig deutlich steigt, kann ein Teil dieses Effekts auf den Neuigkeitswert zurückzuführen sein. Daher fordern Arbeitsforscher längere Beobachtungszeiträume. Sie betonen zudem, dass die Vier-Tage-Woche kein einzelnes Instrument ist, das unabhängig von Führung, Personaldecke und Arbeitsorganisation funktioniert. Ein erfolgreiches Modell müsse an Branche und Tätigkeit angepasst werden.\n\nFür Beschäftigte ist nicht nur die Zahl der Arbeitstage relevant. Planbarkeit, Autonomie und die Möglichkeit, konzentriert zu arbeiten, spielen ebenfalls eine große Rolle. Einige Untersuchungen zeigen sogar, dass Beschäftigte eine geringere Wochenarbeitszeit mit etwas weniger Einkommen akzeptieren würden, wenn sie dafür verlässlich über ihre Zeit verfügen könnten. Das spricht dafür, Arbeitszeitpolitik nicht auf eine einzige Kennzahl zu reduzieren.\n\nIn der öffentlichen Debatte wird die Vier-Tage-Woche häufig entweder als Zukunftsmodell oder als unrealistische Wohlfühlidee dargestellt. Die Forschung zeichnet ein differenzierteres Bild: Unter passenden Bedingungen kann sie Vorteile bringen, doch sie löst weder Personalmangel noch schlechte Prozesse von selbst. Entscheidend ist somit weniger die Zahl Vier als die Frage, wie Arbeit organisiert wird.","items":[{"q":"Warum ist der Begriff Vier-Tage-Woche laut Text nicht eindeutig?","o":["Weil nur öffentliche Betriebe ihn nutzen.","Weil unterschiedliche Modelle dahinterstehen.","Weil die Wochenarbeitszeit immer gleich bleibt."],"a":1},{"q":"Warum mahnen Forschende bei Pilotstudien zur Vorsicht?","o":["Teilnehmende Unternehmen können nicht repräsentativ sein.","Die Produktivität wird nie gemessen.","Die Projekte dauern immer zu lange."],"a":0},{"q":"Wie kann Produktivität trotz weniger Arbeitszeit stabil bleiben?","o":["Durch längere Pausen.","Durch effizientere Abläufe und weniger unwirksame Tätigkeiten.","Durch zusätzliche unbezahlte Arbeit."],"a":1},{"q":"Welches Risiko nennt der Text bei Arbeitsverdichtung?","o":["Mehr Zeitdruck an den Arbeitstagen.","Zu viele freie Mitarbeiter.","Sinkende Öffnungszeiten in allen Branchen."],"a":0},{"q":"Warum sind längere Studien nötig?","o":["Um einen möglichen Neuigkeitseffekt von dauerhaften Wirkungen zu trennen.","Weil bisher keine Daten existieren.","Weil nur Gehälter untersucht wurden."],"a":0},{"q":"Was ist Beschäftigten laut Text ebenfalls wichtig?","o":["Nur die Zahl der Urlaubstage.","Planbarkeit und Autonomie.","Einheitliche Arbeitszeiten für alle Branchen."],"a":1},{"q":"Welche Schlussfolgerung zieht der Text?","o":["Vier Tage sind grundsätzlich optimal.","Die konkrete Arbeitsorganisation ist wichtiger als die reine Zahl der Tage.","Das Modell ist nur im Schichtbetrieb sinnvoll."],"a":1}]},"part3":{"title":"Bölüm 3 · Cümleleri yeniden yerleştirme","segments":["Digitale Lernplattformen versprechen, Unterricht stärker zu individualisieren. "," Lehrkräfte erhalten dadurch detaillierte Informationen über Lernfortschritte. "," Gerade hier beginnt jedoch die Debatte über Datenschutz. "," Solche Daten können pädagogisch hilfreich sein, zugleich lassen sich daraus umfassende Profile ableiten. "," Hinzu kommt, dass algorithmische Empfehlungen nicht neutral sind. "," Werden bestimmte Aufgabentypen häufiger vorgeschlagen, kann dies langfristig beeinflussen, welche Kompetenzen Lernende entwickeln. "," Deshalb fordern Fachleute transparente Kriterien und die Möglichkeit, automatisierte Empfehlungen zu übersteuern. "," Entscheidend ist am Ende, dass Technik pädagogische Entscheidungen unterstützt, nicht ersetzt. "," Nur dann kann Personalisierung einen echten Mehrwert bieten."],"candidates":["A: Systeme können Aufgaben automatisch an das bisherige Leistungsniveau anpassen.","B: Dafür müssen allerdings große Mengen an Nutzungsdaten verarbeitet werden.","C: Aus diesem Grund sollten Schulen sämtliche digitalen Angebote vermeiden.","D: Denn Modelle spiegeln immer auch die Daten und Annahmen wider, auf denen sie beruhen.","E: Eine technische Empfehlung kann also unbemerkt zu einer pädagogischen Vorgabe werden.","F: Gleichzeitig bleibt die professionelle Beurteilung durch Lehrkräfte unverzichtbar.","G: Viele Schulen ersetzen deshalb alle Lehrbücher durch Tablets.","H: Besonders wichtig ist, dass Betroffene nachvollziehen können, wie eine Empfehlung entsteht.","I: Diese Forderung betrifft sowohl Anbieter als auch Bildungseinrichtungen.","J: Personalisierung wird damit zu einer Frage der Kontrolle und Verantwortlichkeit."],"answers":[0,1,9,3,4,7,8,5]},"part4":{"title":"Bölüm 4 · Görüşleri eşleştirme","texts":[{"name":"A · Prof. Berger","text":"Generative KI kann Studierenden beim Strukturieren helfen. Problematisch wird es, wenn der Denkprozess ausgelagert wird. Ich würde die Werkzeuge daher nicht verbieten, sondern Aufgaben so gestalten, dass Zwischenschritte und Quellen transparent gemacht werden müssen."},{"name":"B · Dr. Kaya","text":"Für mich steht Chancengleichheit im Vordergrund. Wenn leistungsfähige Systeme kostenpflichtig sind, dürfen Prüfungen nicht voraussetzen, dass alle Studierenden Zugang haben. Institutionen müssten entweder gleichwertige Zugänge bereitstellen oder die Nutzung begrenzen."},{"name":"C · Lena Hoffmann","text":"Ich nutze KI vor allem, um Gegenargumente zu finden. Das zwingt mich, meine Position zu schärfen. Texte lasse ich aber nicht vollständig erzeugen, weil ich sonst kaum merke, ob ich den Stoff wirklich verstanden habe."},{"name":"D · Markus Voss","text":"Die Debatte konzentriert sich zu stark auf Betrug. Interessanter ist, welche Kompetenzen künftig relevant sind. Wer KI-Ergebnisse prüfen, korrigieren und sinnvoll einordnen kann, besitzt eine neue Form von Fachkompetenz. Hochschulen sollten das systematisch lehren."}],"items":[{"q":"Wer sieht Transparenz über den Arbeitsprozess als zentral an?","a":0},{"q":"Wer betont ungleichen Zugang zu Technik?","a":1},{"q":"Wer nutzt KI gezielt zur Prüfung der eigenen Argumente?","a":2},{"q":"Wer fordert, KI-Kompetenz ausdrücklich zu unterrichten?","a":3},{"q":"Wer lehnt ein generelles Verbot ab?","a":0},{"q":"Wer verbindet die Frage mit Fairness in Prüfungen?","a":1},{"q":"Wer nennt eigenes Verständnis als Grenze der Nutzung?","a":2}]}},"listeningPractice":{"part1":{"title":"Bölüm 1 · Podcast eşleştirme","plays":1,"script":"Willkommen zu „Ideen im Alltag“. Heute stelle ich drei neue Sachbücher vor. Das erste Buch, „Leise Städte“, untersucht, wie Lärm unsere Gesundheit beeinflusst. Besonders stark ist der historische Vergleich: Die Autorin zeigt, wie sich Geräuschquellen seit der Industrialisierung verändert haben und warum absolute Stille in einer Stadt weder realistisch noch unbedingt wünschenswert ist. Das zweite Buch, „Reparieren statt ersetzen“, beschäftigt sich mit Produktdesign. Der Autor besucht Werkstätten, Start-ups und kommunale Reparaturzentren. Er argumentiert, dass langlebige Produkte nicht nur eine technische, sondern auch eine politische Frage sind. Das dritte Buch heißt „Die Kunst des Wartens“. Eine Psychologin verbindet Forschung zu Aufmerksamkeit mit persönlichen Beobachtungen. Sie erklärt, warum Wartezeiten heute als besonders belastend erlebt werden und wie kleine Unterbrechungen sogar kreative Prozesse fördern können.","labels":["A · Leise Städte","B · Reparieren statt ersetzen","C · Die Kunst des Wartens"],"items":[{"q":"Historische Entwicklungen spielen eine wichtige Rolle.","a":0},{"q":"Politische Rahmenbedingungen werden thematisiert.","a":1},{"q":"Persönliche Erfahrungen werden mit Forschung verbunden.","a":2},{"q":"Es geht um die Lebensdauer von Gegenständen.","a":1},{"q":"Ein vermeintlich negativer Zustand kann Vorteile haben.","a":2},{"q":"Völlige Abwesenheit des Problems wird nicht als Ziel dargestellt.","a":0}]},"part2":{"title":"Bölüm 2 · Uzman röportajı","plays":2,"script":"Moderatorin: Herr Neumann, viele Menschen glauben, Multitasking spare Zeit. Stimmt das? Experte: Bei einfachen, automatisierten Tätigkeiten können mehrere Prozesse parallel laufen. Bei anspruchsvollen Denkaufgaben wechseln wir jedoch meist schnell zwischen Aufgaben. Dieser Wechsel kostet Zeit und erhöht die Fehlerquote. Moderatorin: Ist das bei jungen Menschen anders? Experte: Sie sind oft an häufige Unterbrechungen gewöhnt, aber Gewöhnung bedeutet nicht automatisch bessere Leistung. In unseren Studien sehen wir eher, dass Personen ihre eigene Effizienz überschätzen. Moderatorin: Hilft es, Benachrichtigungen auszuschalten? Experte: Ja, allerdings reicht das allein nicht. Wer ständig erwartet, dass eine Nachricht kommen könnte, bleibt innerlich aufmerksam für mögliche Unterbrechungen. Sinnvoll sind deshalb klar definierte Phasen, in denen Kommunikationskanäle geschlossen werden. Moderatorin: Manche Unternehmen führen Fokuszeiten ein. Experte: Das kann funktionieren, wenn die Organisation es ernst meint. Es bringt wenig, zwei Stunden als Fokuszeit zu deklarieren und gleichzeitig schnelle Antworten zu erwarten. Moderatorin: Gibt es Tätigkeiten, bei denen Unterbrechungen sogar nützlich sind? Experte: Bei kreativen Problemen kann eine Pause helfen. Das ist aber etwas anderes als eine zufällige Nachricht. Eine bewusst gewählte Unterbrechung kann Distanz schaffen; unvorhersehbare Unterbrechungen fragmentieren eher die Aufmerksamkeit.","items":[{"q":"Bei komplexen Aufgaben erledigt das Gehirn mehrere Denkprozesse gleichzeitig.","a":1},{"q":"Häufiger Aufgabenwechsel kann die Fehlerquote erhöhen.","a":0},{"q":"Jüngere Menschen sind nachweislich effizienter im Multitasking.","a":1},{"q":"Menschen überschätzen laut Experte teilweise ihre Multitasking-Leistung.","a":0},{"q":"Ausgeschaltete Benachrichtigungen lösen das Problem vollständig.","a":1},{"q":"Fokuszeiten funktionieren nur, wenn Erwartungen im Unternehmen dazu passen.","a":0},{"q":"Der Experte empfiehlt Fokuszeiten von genau zwei Stunden.","a":2},{"q":"Bewusste Pausen können bei kreativen Problemen hilfreich sein.","a":0},{"q":"Jede Form von Unterbrechung wirkt gleich auf Aufmerksamkeit.","a":1}],"labels":["stimmt","stimmt nicht","dazu wird nichts gesagt"]},"part3":{"title":"Bölüm 3 · Tartışma","plays":1,"segments":[{"script":"Moderator: Sollten Innenstädte komplett autofrei werden? Stadtplanerin: Ein vollständiges Verbot klingt einfach, ignoriert aber Lieferverkehr und Menschen mit eingeschränkter Mobilität. Ich plädiere für deutlich weniger privaten Autoverkehr, aber mit klar definierten Ausnahmen. Händler: Mein Hauptproblem ist nicht die Reduktion an sich, sondern die Planbarkeit. Wenn Regeln ständig wechseln, können Betriebe Logistik kaum organisieren.","items":[{"q":"Was fordert die Stadtplanerin?","o":["Ein ausnahmsloses Verbot","Weniger privaten Autoverkehr mit Ausnahmen","Mehr Parkplätze"],"a":1},{"q":"Was kritisiert der Händler vor allem?","o":["Unklare und wechselnde Regeln","Zu viele Fahrräder","Zu wenig Lieferverkehr"],"a":0}]},{"script":"Moderator: Häufig heißt es, weniger Autos machten Zentren automatisch attraktiver. Händler: Das kann stimmen, wenn gleichzeitig gute Erreichbarkeit geschaffen wird. Wer nur Parkplätze entfernt, ohne ÖPNV und Lieferzonen zu verbessern, verlagert Probleme. Stadtplanerin: Genau deshalb müssen Maßnahmen als Paket geplant werden. Aufenthaltsqualität entsteht nicht durch Verbote allein.","items":[{"q":"Wovon hängt Attraktivität laut Händler ab?","o":["Nur von weniger Parkplätzen","Von alternativer Erreichbarkeit und Logistik","Von höheren Mieten"],"a":1},{"q":"Worin sind sich beide einig?","o":["Einzelmaßnahmen reichen nicht","Autos müssen unverändert bleiben","ÖPNV spielt keine Rolle"],"a":0}]},{"script":"Moderator: Wie reagieren Bewohner? Stadtplanerin: Am Anfang gibt es oft Widerstand, weil Menschen Verluste stärker wahrnehmen als mögliche Gewinne. Nach Umbauten steigt die Zustimmung häufig, wenn der öffentliche Raum tatsächlich besser nutzbar wird. Händler: Erfahrungen aus anderen Städten sind hilfreich, aber sie lassen sich nicht eins zu eins übertragen.","items":[{"q":"Wie erklärt die Stadtplanerin anfänglichen Widerstand?","o":["Menschen gewichten Verluste stark","Alle sind gegen Veränderungen","Es fehlen Daten"],"a":0},{"q":"Was sagt der Händler zu anderen Städten?","o":["Erfahrungen sind wertlos","Modelle müssen an lokale Bedingungen angepasst werden","Man soll alles kopieren"],"a":1}]},{"script":"Moderator: Was wäre ein vernünftiger nächster Schritt? Händler: Pilotzonen mit klaren Messkriterien. Dann kann man sehen, wie sich Umsätze, Lieferzeiten und Besucherzahlen entwickeln. Stadtplanerin: Dem stimme ich zu. Zusätzlich würde ich Luftqualität und Aufenthaltsdauer messen. Entscheidungen sollten danach auf mehreren Kriterien beruhen, nicht nur auf Verkehrszahlen.","items":[{"q":"Was schlägt der Händler vor?","o":["Sofortiges dauerhaftes Verbot","Pilotzonen mit Messkriterien","Keine Veränderung"],"a":1},{"q":"Was ergänzt die Stadtplanerin?","o":["Weitere Qualitätsindikatoren","Nur Verkehrszahlen zählen","Keine Messung nötig"],"a":0}]}]},"part4":{"title":"Bölüm 4 · Sunum","plays":2,"script":"Sehr geehrte Damen und Herren, ich möchte heute über Bürgerwissenschaft, auch Citizen Science genannt, sprechen. Gemeint sind Forschungsprojekte, an denen Menschen ohne professionelle wissenschaftliche Ausbildung aktiv mitwirken. Besonders bekannt sind Projekte zur Beobachtung von Vögeln, Insekten oder Wetterphänomenen. Der größte Vorteil liegt in der räumlichen und zeitlichen Reichweite: Ein kleines Forschungsteam könnte unmöglich gleichzeitig Daten aus Tausenden Orten sammeln. Freiwillige können diese Lücke schließen. Allerdings entstehen neue methodische Fragen. Wenn viele Personen Daten erfassen, unterscheiden sich Erfahrung und Genauigkeit. Gute Projekte reagieren darauf mit klaren Protokollen, Schulungen und automatischen Plausibilitätsprüfungen. Ein zweiter Punkt betrifft Motivation. Teilnehmende bleiben eher langfristig aktiv, wenn sie erfahren, wozu ihre Daten beitragen. Deshalb veröffentlichen erfolgreiche Projekte Zwischenergebnisse und erklären, wie einzelne Beobachtungen in größere Analysen einfließen. Bürgerwissenschaft ersetzt professionelle Forschung nicht. Sie erweitert vielmehr die Datengrundlage und kann Themen sichtbar machen, die sonst wenig Aufmerksamkeit erhalten. Gleichzeitig entsteht ein gesellschaftlicher Effekt: Wer selbst Daten erhebt, entwickelt oft ein genaueres Verständnis dafür, wie wissenschaftliche Erkenntnisse zustande kommen – einschließlich Unsicherheit, Fehlern und notwendigen Kontrollen. Damit Citizen Science zuverlässig funktioniert, müssen Aufgaben jedoch so gestaltet sein, dass sie ohne Spezialgeräte und mit vertretbarem Aufwand durchgeführt werden können. Besonders komplexe Messungen bleiben daher Fachleuten vorbehalten. Die Zukunft liegt vermutlich in hybriden Modellen, in denen große Freiwilligennetze mit professionellen Laboren und digitalen Prüfverfahren zusammenarbeiten.","items":[{"q":"Was ist ein Hauptvorteil von Citizen Science?","o":["Forschung wird ohne Fachleute möglich","Große räumliche und zeitliche Datenerfassung","Jede Messung wird genauer"],"a":1},{"q":"Welches Problem entsteht durch viele Freiwillige?","o":["Unterschiedliche Datengenauigkeit","Zu wenige Orte","Keine Motivation von Forschern"],"a":0},{"q":"Wie sichern gute Projekte Qualität?","o":["Sie verzichten auf Regeln","Durch Protokolle, Schulung und Plausibilitätsprüfungen","Nur durch Bezahlung"],"a":1},{"q":"Was stärkt langfristige Motivation?","o":["Wenn Ergebnisse und Nutzen sichtbar werden","Wenn Daten geheim bleiben","Wenn Aufgaben schwieriger werden"],"a":0},{"q":"Wie wird Citizen Science im Vortrag eingeordnet?","o":["Als Ersatz professioneller Forschung","Als Ergänzung professioneller Forschung","Als reine Bildungsmaßnahme"],"a":1},{"q":"Welchen gesellschaftlichen Effekt nennt der Vortrag?","o":["Mehr Verständnis für wissenschaftliche Prozesse","Weniger Interesse an Wissenschaft","Sichere Beseitigung aller Unsicherheit"],"a":0},{"q":"Was bleibt eher Fachleuten vorbehalten?","o":["Einfache Beobachtungen","Komplexe Messungen mit Spezialanforderungen","Das Lesen von Zwischenergebnissen"],"a":1}]}},"writingForum":[{"id":"wf1","title":"Üniversitede zorunlu staj","prompt":"Bir eğitim forumunda üniversite programlarında zorunlu stajın gerekli olup olmadığını tartışın.","points":["Zorunlu stajın bir avantajını açıklayın.","Olası bir dezavantajı gerekçelendirin.","Kendi ülkenizden veya deneyiminizden bir örnek verin.","Hangi koşullarda zorunlu olmasını uygun gördüğünüzü değerlendirin."],"target":230,"model":"Zorunlu staj, teorik bilginin iş yaşamıyla bağını güçlendirebilir. Özellikle öğrenciler mesleğin günlük gerçeklerini henüz tanımıyorsa, kısa süreli de olsa uygulama deneyimi kararlarını daha bilinçli hâle getirir. Bununla birlikte, her stajın otomatik olarak nitelikli bir öğrenme ortamı sunduğunu varsaymak doğru değildir. Öğrencilerin yalnızca rutin işler yaptığı ve ücret almadığı durumlarda zorunluluk haksız bir yük yaratabilir.\n\nBu nedenle bana göre belirleyici olan “staj olsun mu olmasın mı?” sorusu değil, stajın hangi standartlara göre düzenlendiğidir. Örneğin üniversite, öğrenme hedeflerini önceden belirleyebilir ve kurumdan düzenli geribildirim isteyebilir. Ayrıca ekonomik durumu sınırlı öğrencilerin ücretsiz çalışmak zorunda kalmaması için asgari bir ödeme veya burs sistemi düşünülmelidir.\n\nTürkiye’de ve Almanya’da bazı programlarda uygulama dönemi zaten önemli bir rol oynuyor. Başarılı örneklerde öğrenci, stajın ardından yaptığı işi analiz eden bir rapor hazırlıyor. Bu, deneyimi yalnızca “işte bulunmak” olmaktan çıkarıp öğrenme sürecine dönüştürüyor.\n\nSonuç olarak zorunlu stajı genel olarak destekliyorum; ancak yalnızca kalite ölçütleri, akademik rehberlik ve makul maddi koşullar garanti edildiğinde."},{"id":"wf2","title":"Dört günlük çalışma haftası","prompt":"Bir çevrimiçi forumda dört günlük çalışma haftasının yaygınlaştırılıp yaygınlaştırılmaması hakkında yazın.","points":["Modelin olası faydalarını açıklayın.","Bir uygulama sorununu tartışın.","Bir örnekle görüşünüzü destekleyin.","Sonuçta hangi yaklaşımı önerdiğinizi belirtin."],"target":230,"model":""},{"id":"wf3","title":"Yapay zekâ ile eğitim","prompt":"Üniversitelerde üretken yapay zekâ kullanımının nasıl düzenlenmesi gerektiğini tartışın.","points":["Bir fırsatı açıklayın.","Bir riski gerekçelendirin.","Somut bir kullanım örneği verin.","Kendi düzenleme önerinizi sunun."],"target":230,"model":""},{"id":"wf4","title":"Şehir merkezinde otomobil","prompt":"Şehir merkezlerinde özel otomobil kullanımının ciddi biçimde sınırlandırılması hakkında görüş yazın.","points":["Bir çevresel veya sosyal faydayı açıklayın.","Bir karşı argümanı ele alın.","Başka bir şehir/ülkeden örnek verin.","Dengeli bir çözüm önerin."],"target":230,"model":""},{"id":"wf5","title":"Ücretsiz yükseköğretim","prompt":"Yükseköğretimin herkes için tamamen ücretsiz olması gerekip gerekmediğini tartışın.","points":["Bir eşitlik argümanı sunun.","Finansman açısından bir sorun ele alın.","Bir sistem örneği verin.","Kendi sonucunuzu gerekçelendirin."],"target":230,"model":""},{"id":"wf6","title":"Uzaktan çalışma hakkı","prompt":"Uygun mesleklerde çalışanların haftanın belirli günlerinde uzaktan çalışma hakkına sahip olup olmaması üzerine yazın.","points":["Çalışan açısından bir faydayı açıklayın.","İşveren açısından bir riski tartışın.","Bir örnek verin.","Hangi koşullarda hakkı desteklediğinizi açıklayın."],"target":230,"model":""}],"writingEmail":[{"id":"we1","title":"Kütüphane çalışma alanı","prompt":"Üniversite kütüphanesinde rezervasyon yaptığınız sessiz çalışma odası sürekli grup toplantıları için kullanılıyor. Kütüphane yönetimine yazın.","points":["Sorunu açıklayın.","Bunun çalışmanızı nasıl etkilediğini belirtin.","Somut bir çözüm önerin.","Nazikçe hızlı yanıt/anlayış isteyin."],"target":120,"model":"Sehr geehrte Damen und Herren,\n\nich möchte Sie auf ein Problem mit den als „still“ ausgewiesenen Arbeitsräumen aufmerksam machen. Obwohl ich mehrfach einen Einzelarbeitsplatz reserviert habe, wurden die Räume gleichzeitig für lautere Gruppentreffen genutzt. Dadurch ist konzentriertes Arbeiten, insbesondere während meiner Prüfungsvorbereitung, kaum möglich.\n\nIch schlage vor, die Nutzungsregeln bei der Reservierung deutlicher anzuzeigen und für Gruppen separate Räume vorzusehen. Zusätzlich könnte das Bibliothekspersonal bei wiederholten Verstößen gezielt darauf hinweisen.\n\nIch wäre Ihnen dankbar, wenn Sie prüfen könnten, wie die vereinbarte ruhige Nutzung künftig besser gewährleistet werden kann. Vielen Dank für Ihr Verständnis.\n\nMit freundlichen Grüßen\nAylin Demir"},{"id":"we2","title":"Seminer tarihi değişikliği","prompt":"Bir seminer tarihi kısa süre önce değiştirildi ve yeni tarih zorunlu bir iş vardiyanızla çakışıyor. Öğretim görevlisine yazın.","points":["Durumu açıklayın.","Neden katılamadığınızı belirtin.","Bir alternatif önerin.","Anlayış rica edin."],"target":120,"model":""},{"id":"we3","title":"Yanlış fatura","prompt":"Bir dil kursu size anlaşılmış ücretten daha yüksek bir fatura gönderdi. Kurs yönetimine yazın.","points":["Farkı açıklayın.","Anlaşmayı referans gösterin.","Düzeltme önerin/isteyin.","Nazik kapanış yapın."],"target":120,"model":""},{"id":"we4","title":"Ofiste gürültü","prompt":"Yeni açık ofiste sürekli telefon görüşmeleri işinizi ciddi biçimde etkiliyor. Yöneticinize yazın.","points":["Sorunu somutlaştırın.","İş üzerindeki etkisini açıklayın.","Uygulanabilir çözüm önerin.","İşbirliğine açık olduğunuzu gösterin."],"target":120,"model":""},{"id":"we5","title":"Kurs materyali erişimi","prompt":"Çevrimiçi kurs materyallerine iki gündür erişemiyorsunuz ve son teslim tarihi yaklaşıyor. Teknik desteğe yazın.","points":["Sorunu tarif edin.","Denediğiniz adımları belirtin.","Acil çözüm/uzatma önerin.","Yanıt rica edin."],"target":120,"model":""},{"id":"we6","title":"Toplantı gündemi","prompt":"Toplantı gündeminde sizin alanınızla ilgili kritik bir konu eksik. Organizatöre yazın.","points":["Eksik konuyu belirtin.","Neden önemli olduğunu açıklayın.","Gündeme eklenmesini önerin.","Nazikçe teyit isteyin."],"target":120,"model":""}],"speakingPresentations":[{"id":"sp1","title":"Üniversitelerde yapay zekâ","intro":"Bir seminerde üretken yapay zekânın üniversite eğitimindeki rolü üzerine kısa bir sunum yapın.","points":["Somut bir kullanım örneği verin.","Bir fırsatı ve bir riski karşılaştırın.","Hangi kuralların gerekli olduğunu açıklayın.","Kendi değerlendirmenizle sonuçlandırın."],"questions":["Welche Kompetenz sollten Studierende im Umgang mit KI unbedingt lernen?","Wo würden Sie eine klare Grenze ziehen?"]},{"id":"sp2","title":"Şehirde yeşil alan","intro":"Büyük şehirlerde yeşil alanların genişletilmesi hakkında sunum yapın.","points":["Bir güncel sorunu örnekleyin.","Çevresel ve sosyal etkileri açıklayın.","Olası maliyet/çatışmaları tartışın.","Bir öncelik önerin."],"questions":["Wer sollte solche Projekte finanzieren?","Wie kann man Nutzungskonflikte lösen?"]},{"id":"sp3","title":"Dört günlük çalışma haftası","intro":"Dört günlük çalışma haftasının fırsat ve sınırlarını sunun.","points":["Bir model tanımlayın.","Fayda ve riski tartışın.","Bir sektör örneği verin.","Kendi koşullu görüşünüzü belirtin."],"questions":["Für welche Branchen wäre das Modell besonders schwierig?","Wie könnte man Produktivität sinnvoll messen?"]},{"id":"sp4","title":"Üniversitede devam zorunluluğu","intro":"Üniversite derslerinde devam zorunluluğunu değerlendirin.","points":["Bir gerekçe sunun.","Karşı görüşü ele alın.","Kendi deneyiminizden örnek verin.","Alternatif bir model önerin."],"questions":["Sollte Anwesenheit benotet werden?","Wie könnte man aktive Teilnahme anders messen?"]},{"id":"sp5","title":"Toplu taşıma ücretsiz mi?","intro":"Şehir içi toplu taşımanın ücretsiz olması gerekip gerekmediğini tartışan bir sunum yapın.","points":["Bir avantaj açıklayın.","Finansman sorununu ele alın.","Bir şehir örneği verin.","Kendi çözümünüzü önerin."],"questions":["Wer sollte die Kosten tragen?","Würde kostenloser ÖPNV automatisch den Autoverkehr senken?"]},{"id":"sp6","title":"Uzaktan çalışma","intro":"Uzaktan çalışmanın uzun vadeli etkileri üzerine sunum yapın.","points":["Çalışan açısından bir etki açıklayın.","Şirket açısından bir etki açıklayın.","Takım iletişimini değerlendirin.","Hibrit bir model önerin."],"questions":["Wie viel Präsenz halten Sie für sinnvoll?","Welche Aufgaben eignen sich nicht fürs Homeoffice?"]}],"speakingDiscussions":[{"id":"sd1","title":"KI ile yazılmış ödevler","input":"Bir üniversite, üretken yapay zekâ ile hazırlanmış ödevlerin tamamen yasaklanmasını tartışıyor.","points":["Yasak ne kadar uygulanabilir?","Öğrenme hedefleri nasıl korunur?","Şeffaflık kuralları yeterli olabilir mi?","Ortak bir öneri geliştirin."]},{"id":"sd2","title":"Şehir merkezinde araç kısıtlaması","input":"Belediye, merkezde özel araç trafiğini yarıya indirmeyi planlıyor.","points":["Çevresel etkiler","Esnaf ve erişilebilirlik","Alternatif ulaşım","Ortak öncelikler"]},{"id":"sd3","title":"Zorunlu gönüllü hizmet","input":"Genç yetişkinler için altı aylık toplumsal hizmet zorunluluğu öneriliyor.","points":["Toplumsal fayda","Bireysel özgürlük","Eğitim/işe etkisi","Olası alternatif model"]},{"id":"sd4","title":"Dört günlük çalışma haftası","input":"Bir şirket ücret azaltmadan dört günlük haftayı kalıcılaştırmak istiyor.","points":["Verimlilik","Müşteri erişimi","Çalışan yükü","Pilot uygulama ölçütleri"]},{"id":"sd5","title":"Üniversite harcı","input":"Devlet üniversitelerinde düşük miktarlı genel öğrenim harcı öneriliyor.","points":["Finansman","Eşitlik","Muafiyet/burs","Ortak çözüm"]},{"id":"sd6","title":"Sosyal medyada yaş sınırı","input":"16 yaş altı için sosyal medya hesaplarına daha sıkı yaş doğrulaması öneriliyor.","points":["Çocuk koruma","Mahremiyet","Uygulanabilirlik","Ebeveyn/eğitim rolü"]}],"goetheMock":{"reading":{"part1":{"title":"Bölüm 1 · Sözcük boşlukları","text":"Solaranlagen und begrünte Dächer wurden lange als konkurrierende Nutzungen betrachtet. Neuere Planungsansätze versuchen jedoch, beide Systeme auf derselben Fläche ___(1)___. Pflanzen können durch Verdunstung und Schatten dazu beitragen, dass sich Solarmodule an heißen Tagen weniger stark erwärmen und dadurch effizienter ___(2)___. Allerdings eignet sich nicht jedes Gebäude für eine solche Kombination. Tragfähigkeit, Windlast und Zugang für die Wartung müssen bereits in der Planung ___(3)___ werden. Fachleute weisen außerdem darauf hin, dass die Auswahl der Pflanzen an die besonderen Bedingungen auf dem Dach ___(4)___ sein muss. Arten, die viel Wasser benötigen, sind in trockenen Sommern problematisch. Gut geplante Systeme können dagegen Regenwasser zurückhalten und die Artenvielfalt fördern. Ob sich die höheren Anfangskosten langfristig ___(5)___, hängt von Standort, Bauweise und Pflege ab. Entscheidend ist deshalb, die Wirkung nicht anhand einzelner Beispiele zu beurteilen, ___(6)___ über mehrere Jahre systematisch zu erfassen. Erst dann lässt sich verlässlich sagen, unter welchen Bedingungen sich beide Nutzungen gegenseitig ___(7)___ und wo Zielkonflikte entstehen. Kommunen, die solche Projekte fördern möchten, sollten daher nicht nur technische Standards festlegen, ___(8)___ auch Beratung und langfristige Evaluation einplanen.","items":[{"o":["zu verbinden","verbunden","verbindlich","Verbindung"],"a":0},{"o":["arbeiten","wirken","leisten","erzeugen"],"a":1},{"o":["berücksichtigt","beobachtet","begründet","verhindert"],"a":0},{"o":["angepasst","angewiesen","aufgeteilt","ausgelöst"],"a":0},{"o":["auszahlen","auszahlt","bezahlen","bezahlt"],"a":1},{"o":["sondern","obwohl","damit","während"],"a":0},{"o":["ergänzen","ersetzen","vermeiden","begrenzen"],"a":0},{"o":["aber","sondern","dennoch","obwohl"],"a":1}]},"part2":{"title":"Bölüm 2 · Ana fikirler ve ayrıntılı bilgiler","text":"Viele Hochschulen versuchen seit einigen Jahren, Prinzipien der offenen Wissenschaft stärker zu verankern. Häufig wird darunter vor allem verstanden, wissenschaftliche Artikel kostenlos zugänglich zu machen. Open Science umfasst jedoch deutlich mehr: Auch Forschungsdaten, Methoden und teilweise sogar Auswertungsschritte sollen so dokumentiert werden, dass andere Forschende Ergebnisse nachvollziehen und - soweit möglich - überprüfen können.\n\nBefürworter sehen darin einen wichtigen Beitrag zur Qualitätssicherung. Wenn Datensätze und Analysewege zugänglich sind, lassen sich Fehler leichter entdecken und Ergebnisse eher reproduzieren. Zudem können bereits erhobene Daten für neue Fragestellungen genutzt werden. Das spart unter Umständen Zeit und Ressourcen. Allerdings ist nicht jeder Datensatz ohne Weiteres veröffentlichbar. Besonders in Medizin, Psychologie und Sozialforschung können Angaben enthalten sein, die Rückschlüsse auf einzelne Personen zulassen. Datenschutz und informierte Einwilligung müssen deshalb von Beginn an berücksichtigt werden.\n\nEin weiteres Problem ist der Arbeitsaufwand. Daten so aufzubereiten, dass Außenstehende sie tatsächlich verstehen, erfordert klare Dokumentation, standardisierte Formate und häufig zusätzliche Metadaten. Forschende kritisieren, dass diese Arbeit in vielen Karrieresystemen bislang kaum anerkannt wird. Wer Zeit in saubere Dokumentation investiert, hat nicht automatisch bessere Chancen bei Bewerbungen oder Förderanträgen. Fachleute fordern daher, offene Forschungspraktiken auch bei Leistungsbewertungen stärker zu berücksichtigen.\n\nKontrovers diskutiert wird außerdem, ob Offenheit in jedem Stadium sinnvoll ist. Bei laufenden Projekten kann eine zu frühe Veröffentlichung Ideen gefährden, an denen Teams über Jahre gearbeitet haben. Andere halten dagegen, dass transparente Vorregistrierungen gerade verhindern können, dass nur erwünschte Resultate veröffentlicht werden. Ein einheitliches Modell für alle Disziplinen dürfte daher kaum funktionieren.\n\nDie Debatte zeigt, dass offene Wissenschaft weder eine einfache technische Lösung noch ein Selbstzweck ist. Sie kann Vertrauen und Nachprüfbarkeit fördern, wenn rechtliche, ethische und organisatorische Voraussetzungen stimmen. Entscheidend ist weniger, möglichst alles öffentlich zu machen, als nachvollziehbar zu begründen, was geteilt werden kann, was geschützt werden muss und wie wissenschaftliche Arbeit dafür angemessen honoriert wird.","items":[{"q":"Was umfasst Open Science laut Text über frei zugängliche Artikel hinaus?","o":["Nur öffentliche Vorträge","Auch Daten, Methoden und Auswertungsschritte","Ausschließlich kostenlose Lehrbücher"],"a":1},{"q":"Welchen Vorteil nennen Befürworter?","o":["Fehler und Ergebnisse lassen sich leichter überprüfen.","Forschung wird grundsätzlich billiger.","Datenschutz wird überflüssig."],"a":0},{"q":"Warum können Forschungsdaten nicht immer vollständig veröffentlicht werden?","o":["Weil Dateien meist zu groß sind.","Weil Rückschlüsse auf Personen möglich sein können.","Weil Zeitschriften dies grundsätzlich verbieten."],"a":1},{"q":"Welche Schwierigkeit betrifft die Aufbereitung von Daten?","o":["Sie erfordert zusätzliche Dokumentation und Zeit.","Sie ist nur mit kommerzieller Software möglich.","Sie verhindert weitere Forschung mit den Daten."],"a":0},{"q":"Was wird an heutigen Karrieresystemen kritisiert?","o":["Offene Forschungspraktiken werden oft zu wenig anerkannt.","Veröffentlichungen spielen überhaupt keine Rolle.","Forschende dürfen keine Metadaten erstellen."],"a":0},{"q":"Warum ist eine zu frühe Offenlegung umstritten?","o":["Sie kann langjährig entwickelte Ideen gefährden.","Sie macht Vorregistrierungen unmöglich.","Sie ist in allen Fächern gesetzlich verboten."],"a":0},{"q":"Welche Schlussfolgerung zieht der Text?","o":["Alle Forschungsdaten sollten ohne Ausnahme öffentlich sein.","Offenheit muss fachlich, rechtlich und ethisch differenziert gestaltet werden.","Open Science ist vor allem eine technische Speicherfrage."],"a":1}]},"part3":{"title":"Bölüm 3 · Cümleleri yeniden yerleştirme","segments":["Da sommerliche Hitze in Städten zunimmt, gewinnt die kühlende Wirkung von Bäumen an Bedeutung. ___(1)___","Pauschale Angaben wie „ein Baum senkt die Temperatur um mehrere Grad“ sind deshalb nur begrenzt aussagekräftig. ___(2)___","Hinzu kommt, dass Stadtbäume selbst stärker unter Trockenheit und Hitze leiden. ___(3)___","Planerinnen und Planer setzen daher zunehmend auf eine größere Artenvielfalt. ___(4)___","Vielfalt allein reicht jedoch nicht aus. Auch der Wasserbedarf muss berücksichtigt werden. ___(5)___","Ein weiterer Faktor ist das Alter der Bäume. Große, etablierte Kronen können deutlich mehr Schatten spenden als junge Pflanzungen. ___(6)___","Bei neuen Programmen stellt sich außerdem die Frage, in welchen Stadtteilen zuerst investiert werden soll. ___(7)___","Damit wird Stadtbegrünung nicht nur zu einer ästhetischen, sondern auch zu einer langfristigen Gesundheits- und Gerechtigkeitsfrage. ___(8)___"],"candidates":["A: Denn die Wirkung hängt unter anderem von Art, Alter, Kronengröße und Wasserversorgung ab.","B: Dieses Thema spielt ausschließlich in ländlichen Regionen eine Rolle.","C: Klimamodelle deuten darauf hin, dass manche traditionell verwendeten Arten künftig stärker unter Stress geraten.","D: Monokulturen können bei einer einzigen Krankheit besonders große Verluste erleiden.","E: Dadurch sinken die Pflegekosten in jedem Fall auf null.","F: Das Fällen ausgewachsener Bäume lässt sich daher kurzfristig kaum durch Neupflanzungen ausgleichen.","G: Priorität sollten besonders heiße und bislang schlecht mit Grünflächen versorgte Quartiere erhalten.","H: Vor allem in trockenen Regionen muss geklärt werden, woher zusätzliches Bewässerungswasser kommen kann.","I: Ziel sollte es sein, in jeder Straße dieselbe Baumart zu pflanzen.","J: Der Blick verschiebt sich damit von heutigen Standortbedingungen auf die Widerstandsfähigkeit der nächsten Jahrzehnte."],"answers":[0,9,2,3,7,5,6,4]},"part4":{"title":"Bölüm 4 · Görüşleri eşleştirme","texts":[{"name":"A · Dr. Richter","text":"Aufzeichnungen von Lehrveranstaltungen können das Nacharbeiten erleichtern. Eine permanente Aufnahme kann aber offene Diskussionen hemmen, besonders bei sensiblen Themen. Deshalb sollte je nach Veranstaltungsform entschieden werden."},{"name":"B · Prof. Lang","text":"Ich halte Aufzeichnungen grundsätzlich für sinnvoll. Studierende mit Krankheit, Betreuungspflichten oder Sprachbarrieren profitieren besonders. Entscheidend ist, dass Lehrende wissen, wann aufgezeichnet wird und welche Beiträge später veröffentlicht werden."},{"name":"C · Dr. Seidel","text":"Die Debatte konzentriert sich zu stark auf Technik. Eine Aufnahme ersetzt keine gute Lehrgestaltung. Wenn Studierende wissen, dass alles später verfügbar ist, kann sogar die aktive Teilnahme sinken. Aufzeichnungen sollten daher nur ergänzend eingesetzt werden."},{"name":"D · Prof. Kramer","text":"Bei großen Vorlesungen überwiegen für mich die Vorteile. In kleinen Seminaren mit persönlicher Diskussion würde ich dagegen meist darauf verzichten. Eine einheitliche Regel für alle Lehrveranstaltungen wäre pädagogisch wenig sinnvoll."}],"items":[{"q":"Wer warnt ausdrücklich davor, dass Aufzeichnungen offene Diskussionen beeinträchtigen können?","a":0},{"q":"Wer betont besonders den Nutzen für Studierende mit erschwertem Zugang zur Veranstaltung?","a":1},{"q":"Wer befürchtet, dass die aktive Teilnahme durch die spätere Verfügbarkeit sinken kann?","a":2},{"q":"Wer unterscheidet klar zwischen großen Vorlesungen und kleinen Seminaren?","a":3},{"q":"Wer hält transparente Regeln darüber, was aufgezeichnet und veröffentlicht wird, für entscheidend?","a":1},{"q":"Wer argumentiert, dass Technik gute Didaktik nicht ersetzen kann?","a":2},{"q":"Wer lehnt eine einheitliche Regel für alle Veranstaltungsformen ab?","a":3}]}},"listening":{"part1":{"title":"Bölüm 1 · Podcast eşleştirme","plays":1,"script":"Willkommen zu „Ideen im Alltag“. Heute stelle ich drei neue Sachbücher vor. Das erste Buch, „Leise Städte“, untersucht, wie Lärm unsere Gesundheit beeinflusst. Besonders stark ist der historische Vergleich: Die Autorin zeigt, wie sich Geräuschquellen seit der Industrialisierung verändert haben und warum absolute Stille in einer Stadt weder realistisch noch unbedingt wünschenswert ist. Das zweite Buch, „Reparieren statt ersetzen“, beschäftigt sich mit Produktdesign. Der Autor besucht Werkstätten, Start-ups und kommunale Reparaturzentren. Er argumentiert, dass langlebige Produkte nicht nur eine technische, sondern auch eine politische Frage sind. Das dritte Buch heißt „Die Kunst des Wartens“. Eine Psychologin verbindet Forschung zu Aufmerksamkeit mit persönlichen Beobachtungen. Sie erklärt, warum Wartezeiten heute als besonders belastend erlebt werden und wie kleine Unterbrechungen sogar kreative Prozesse fördern können.","labels":["A · Leise Städte","B · Reparieren statt ersetzen","C · Die Kunst des Wartens"],"items":[{"q":"Historische Entwicklungen spielen eine wichtige Rolle.","a":0},{"q":"Politische Rahmenbedingungen werden thematisiert.","a":1},{"q":"Persönliche Erfahrungen werden mit Forschung verbunden.","a":2},{"q":"Es geht um die Lebensdauer von Gegenständen.","a":1},{"q":"Ein vermeintlich negativer Zustand kann Vorteile haben.","a":2},{"q":"Völlige Abwesenheit des Problems wird nicht als Ziel dargestellt.","a":0}]},"part2":{"title":"Bölüm 2 · Uzman röportajı","plays":2,"script":"Moderatorin: Herr Neumann, viele Menschen glauben, Multitasking spare Zeit. Stimmt das? Experte: Bei einfachen, automatisierten Tätigkeiten können mehrere Prozesse parallel laufen. Bei anspruchsvollen Denkaufgaben wechseln wir jedoch meist schnell zwischen Aufgaben. Dieser Wechsel kostet Zeit und erhöht die Fehlerquote. Moderatorin: Ist das bei jungen Menschen anders? Experte: Sie sind oft an häufige Unterbrechungen gewöhnt, aber Gewöhnung bedeutet nicht automatisch bessere Leistung. In unseren Studien sehen wir eher, dass Personen ihre eigene Effizienz überschätzen. Moderatorin: Hilft es, Benachrichtigungen auszuschalten? Experte: Ja, allerdings reicht das allein nicht. Wer ständig erwartet, dass eine Nachricht kommen könnte, bleibt innerlich aufmerksam für mögliche Unterbrechungen. Sinnvoll sind deshalb klar definierte Phasen, in denen Kommunikationskanäle geschlossen werden. Moderatorin: Manche Unternehmen führen Fokuszeiten ein. Experte: Das kann funktionieren, wenn die Organisation es ernst meint. Es bringt wenig, zwei Stunden als Fokuszeit zu deklarieren und gleichzeitig schnelle Antworten zu erwarten. Moderatorin: Gibt es Tätigkeiten, bei denen Unterbrechungen sogar nützlich sind? Experte: Bei kreativen Problemen kann eine Pause helfen. Das ist aber etwas anderes als eine zufällige Nachricht. Eine bewusst gewählte Unterbrechung kann Distanz schaffen; unvorhersehbare Unterbrechungen fragmentieren eher die Aufmerksamkeit.","items":[{"q":"Bei komplexen Aufgaben erledigt das Gehirn mehrere Denkprozesse gleichzeitig.","a":1},{"q":"Häufiger Aufgabenwechsel kann die Fehlerquote erhöhen.","a":0},{"q":"Jüngere Menschen sind nachweislich effizienter im Multitasking.","a":1},{"q":"Menschen überschätzen laut Experte teilweise ihre Multitasking-Leistung.","a":0},{"q":"Ausgeschaltete Benachrichtigungen lösen das Problem vollständig.","a":1},{"q":"Fokuszeiten funktionieren nur, wenn Erwartungen im Unternehmen dazu passen.","a":0},{"q":"Der Experte empfiehlt Fokuszeiten von genau zwei Stunden.","a":2},{"q":"Bewusste Pausen können bei kreativen Problemen hilfreich sein.","a":0},{"q":"Jede Form von Unterbrechung wirkt gleich auf Aufmerksamkeit.","a":1}],"labels":["stimmt","stimmt nicht","dazu wird nichts gesagt"]},"part3":{"title":"Bölüm 3 · Tartışma","plays":1,"segments":[{"script":"Moderator: Sollten Innenstädte komplett autofrei werden? Stadtplanerin: Ein vollständiges Verbot klingt einfach, ignoriert aber Lieferverkehr und Menschen mit eingeschränkter Mobilität. Ich plädiere für deutlich weniger privaten Autoverkehr, aber mit klar definierten Ausnahmen. Händler: Mein Hauptproblem ist nicht die Reduktion an sich, sondern die Planbarkeit. Wenn Regeln ständig wechseln, können Betriebe Logistik kaum organisieren.","items":[{"q":"Was fordert die Stadtplanerin?","o":["Ein ausnahmsloses Verbot","Weniger privaten Autoverkehr mit Ausnahmen","Mehr Parkplätze"],"a":1},{"q":"Was kritisiert der Händler vor allem?","o":["Unklare und wechselnde Regeln","Zu viele Fahrräder","Zu wenig Lieferverkehr"],"a":0}]},{"script":"Moderator: Häufig heißt es, weniger Autos machten Zentren automatisch attraktiver. Händler: Das kann stimmen, wenn gleichzeitig gute Erreichbarkeit geschaffen wird. Wer nur Parkplätze entfernt, ohne ÖPNV und Lieferzonen zu verbessern, verlagert Probleme. Stadtplanerin: Genau deshalb müssen Maßnahmen als Paket geplant werden. Aufenthaltsqualität entsteht nicht durch Verbote allein.","items":[{"q":"Wovon hängt Attraktivität laut Händler ab?","o":["Nur von weniger Parkplätzen","Von alternativer Erreichbarkeit und Logistik","Von höheren Mieten"],"a":1},{"q":"Worin sind sich beide einig?","o":["Einzelmaßnahmen reichen nicht","Autos müssen unverändert bleiben","ÖPNV spielt keine Rolle"],"a":0}]},{"script":"Moderator: Wie reagieren Bewohner? Stadtplanerin: Am Anfang gibt es oft Widerstand, weil Menschen Verluste stärker wahrnehmen als mögliche Gewinne. Nach Umbauten steigt die Zustimmung häufig, wenn der öffentliche Raum tatsächlich besser nutzbar wird. Händler: Erfahrungen aus anderen Städten sind hilfreich, aber sie lassen sich nicht eins zu eins übertragen.","items":[{"q":"Wie erklärt die Stadtplanerin anfänglichen Widerstand?","o":["Menschen gewichten Verluste stark","Alle sind gegen Veränderungen","Es fehlen Daten"],"a":0},{"q":"Was sagt der Händler zu anderen Städten?","o":["Erfahrungen sind wertlos","Modelle müssen an lokale Bedingungen angepasst werden","Man soll alles kopieren"],"a":1}]},{"script":"Moderator: Was wäre ein vernünftiger nächster Schritt? Händler: Pilotzonen mit klaren Messkriterien. Dann kann man sehen, wie sich Umsätze, Lieferzeiten und Besucherzahlen entwickeln. Stadtplanerin: Dem stimme ich zu. Zusätzlich würde ich Luftqualität und Aufenthaltsdauer messen. Entscheidungen sollten danach auf mehreren Kriterien beruhen, nicht nur auf Verkehrszahlen.","items":[{"q":"Was schlägt der Händler vor?","o":["Sofortiges dauerhaftes Verbot","Pilotzonen mit Messkriterien","Keine Veränderung"],"a":1},{"q":"Was ergänzt die Stadtplanerin?","o":["Weitere Qualitätsindikatoren","Nur Verkehrszahlen zählen","Keine Messung nötig"],"a":0}]}]},"part4":{"title":"Bölüm 4 · Sunum","plays":2,"script":"Sehr geehrte Damen und Herren, ich möchte heute über Bürgerwissenschaft, auch Citizen Science genannt, sprechen. Gemeint sind Forschungsprojekte, an denen Menschen ohne professionelle wissenschaftliche Ausbildung aktiv mitwirken. Besonders bekannt sind Projekte zur Beobachtung von Vögeln, Insekten oder Wetterphänomenen. Der größte Vorteil liegt in der räumlichen und zeitlichen Reichweite: Ein kleines Forschungsteam könnte unmöglich gleichzeitig Daten aus Tausenden Orten sammeln. Freiwillige können diese Lücke schließen. Allerdings entstehen neue methodische Fragen. Wenn viele Personen Daten erfassen, unterscheiden sich Erfahrung und Genauigkeit. Gute Projekte reagieren darauf mit klaren Protokollen, Schulungen und automatischen Plausibilitätsprüfungen. Ein zweiter Punkt betrifft Motivation. Teilnehmende bleiben eher langfristig aktiv, wenn sie erfahren, wozu ihre Daten beitragen. Deshalb veröffentlichen erfolgreiche Projekte Zwischenergebnisse und erklären, wie einzelne Beobachtungen in größere Analysen einfließen. Bürgerwissenschaft ersetzt professionelle Forschung nicht. Sie erweitert vielmehr die Datengrundlage und kann Themen sichtbar machen, die sonst wenig Aufmerksamkeit erhalten. Gleichzeitig entsteht ein gesellschaftlicher Effekt: Wer selbst Daten erhebt, entwickelt oft ein genaueres Verständnis dafür, wie wissenschaftliche Erkenntnisse zustande kommen – einschließlich Unsicherheit, Fehlern und notwendigen Kontrollen. Damit Citizen Science zuverlässig funktioniert, müssen Aufgaben jedoch so gestaltet sein, dass sie ohne Spezialgeräte und mit vertretbarem Aufwand durchgeführt werden können. Besonders komplexe Messungen bleiben daher Fachleuten vorbehalten. Die Zukunft liegt vermutlich in hybriden Modellen, in denen große Freiwilligennetze mit professionellen Laboren und digitalen Prüfverfahren zusammenarbeiten.","items":[{"q":"Was ist ein Hauptvorteil von Citizen Science?","o":["Forschung wird ohne Fachleute möglich","Große räumliche und zeitliche Datenerfassung","Jede Messung wird genauer"],"a":1},{"q":"Welches Problem entsteht durch viele Freiwillige?","o":["Unterschiedliche Datengenauigkeit","Zu wenige Orte","Keine Motivation von Forschern"],"a":0},{"q":"Wie sichern gute Projekte Qualität?","o":["Sie verzichten auf Regeln","Durch Protokolle, Schulung und Plausibilitätsprüfungen","Nur durch Bezahlung"],"a":1},{"q":"Was stärkt langfristige Motivation?","o":["Wenn Ergebnisse und Nutzen sichtbar werden","Wenn Daten geheim bleiben","Wenn Aufgaben schwieriger werden"],"a":0},{"q":"Wie wird Citizen Science im Vortrag eingeordnet?","o":["Als Ersatz professioneller Forschung","Als Ergänzung professioneller Forschung","Als reine Bildungsmaßnahme"],"a":1},{"q":"Welchen gesellschaftlichen Effekt nennt der Vortrag?","o":["Mehr Verständnis für wissenschaftliche Prozesse","Weniger Interesse an Wissenschaft","Sichere Beseitigung aller Unsicherheit"],"a":0},{"q":"Was bleibt eher Fachleuten vorbehalten?","o":["Einfache Beobachtungen","Komplexe Messungen mit Spezialanforderungen","Das Lesen von Zwischenergebnissen"],"a":1}]}},"writing":{"forum":{"id":"mock-w1","title":"Künstliche Intelligenz in der Hochschullehre","prompt":"Sie schreiben einen Diskussionsbeitrag in einem Hochschulforum. Diskutieren Sie, wie der Einsatz generativer künstlicher Intelligenz an Hochschulen geregelt werden sollte.","points":["Erläutern Sie eine Chance.","Begründen Sie ein Risiko.","Veranschaulichen Sie Ihre Argumentation an einem konkreten Beispiel.","Machen Sie einen Vorschlag für sinnvolle Regeln."],"target":230,"model":""},"email":{"id":"mock-w2","title":"Arbeitsraum in der Bibliothek","prompt":"Sie haben in der Universitätsbibliothek wiederholt einen als ruhig ausgewiesenen Arbeitsraum reserviert. Der Raum wird jedoch regelmäßig für laute Gruppentreffen genutzt. Schreiben Sie an die Bibliotheksleitung.","points":["Machen Sie auf das Problem aufmerksam.","Beschreiben Sie die Auswirkungen auf Ihre Arbeit.","Schlagen Sie eine konkrete Lösung vor.","Bitten Sie höflich um eine zeitnahe Reaktion."],"target":120,"model":""}},"speaking":{"presentation":{"id":"mock-sp1","title":"Künstliche Intelligenz an Hochschulen","intro":"Sie nehmen an einem Seminar zu aktuellen Fragen teil und halten einen kurzen Vortrag über generative künstliche Intelligenz in der Hochschullehre.","points":["Geben Sie ein konkretes Anwendungsbeispiel.","Vergleichen Sie eine Chance und ein Risiko.","Erläutern Sie, welche Regeln Sie für notwendig halten.","Schließen Sie mit Ihrer eigenen Bewertung."],"questions":["Welche Kompetenz sollten Studierende im Umgang mit KI unbedingt lernen?","Wo würden Sie eine klare Grenze für den Einsatz ziehen?"]},"discussion":{"id":"mock-sd1","title":"Autoverkehr im Stadtzentrum","input":"Eine Stadt plant, den privaten Autoverkehr im Zentrum innerhalb von fünf Jahren deutlich zu reduzieren.","points":["Umwelt- und Gesundheitswirkungen","Erreichbarkeit und lokale Wirtschaft","Alternativen zum privaten Auto","Prioritäten für einen tragfähigen Kompromiss"]}}},"telc":{"overview":[{"name":"Okuduğunu anlama","detail":"90 dk. · Bölüm 1: 6 metin rekonstrüksiyonu · Bölüm 2: 6 seçici okuma · Bölüm 3: 11 doğru/yanlış/metinde yok + 1 başlık","points":48},{"name":"Dil yapıları","detail":"22 adet 4 seçenekli dilbilgisi/kelime sorusu","points":22},{"name":"Ara","detail":"20 dk.","points":0},{"name":"Dinlediğini anlama","detail":"yakl. 40 dk. · 8 genel eşleştirme · 10 ayrıntı sorusu · 10 bilgi aktarımı","points":48},{"name":"Yazılı anlatım","detail":"70 dk. · 2 konudan 1 uzun tartışmacı/görüş bildiren metin","points":48},{"name":"Sözlü anlatım","detail":"20 dk hazırlık + yakl. 16 dk çift sınav · sunum, partner özeti/sorular ve tartışma","points":48}],"reading1":{"text":"Wissenschaftliche Konferenzen galten lange als unverzichtbare Orte der persönlichen Begegnung. Die Erfahrungen mit digitalen Veranstaltungen haben jedoch gezeigt, dass sich manche Funktionen auch online erfolgreich ___(1)___. Besonders für kurze Fachbeiträge und internationale Teilnahme ___(2)___ virtuelle Formate deutliche Vorteile. Gleichzeitig wurde häufig darauf hingewiesen, dass zufällige Begegnungen und informelle Gespräche online schwerer ___(3)___. Viele Einrichtungen versuchen deshalb inzwischen, beide Formate nicht gegeneinander ___(4)___, sondern je nach Ziel zu kombinieren. Damit hybride Veranstaltungen funktionieren, müssen Online-Teilnehmende aktiv in die Diskussion ___(5)___ werden. Andernfalls bleiben sie leicht in einer passiven Zuschauerrolle. Die zentrale Frage der Konferenzplanung lautet künftig daher nicht mehr „digital oder vor Ort?“, sondern welche Funktion in welchem Format am besten ___(6)___ werden kann.","options":[["verbieten lassen","übersehen lassen","erfüllen lassen","absagen lassen"],["bieten","verschließen","bestreiten","verhindern"],["bestanden","ertragen","verloren","entstehen"],["auszugeben","auszuspielen","auszulassen","auszurichten"],["entzogen","umgangen","einbezogen","verschoben"],["erfüllt","vermutet","verschwiegen","vermieden"]],"answers":[2,0,3,1,2,0]},"reading2":{"texts":[{"id":"A","text":"Die Universitätsbibliothek bleibt künftig auch nachts geöffnet. In den unbesetzten Zeiten ist der Zutritt jedoch nur mit Bibliotheksausweis möglich; eine persönliche Beratung wird dann nicht angeboten."},{"id":"B","text":"Ein neuer Forschungsfonds fördert ausschließlich Projekte, an denen mindestens zwei Teams aus unterschiedlichen Fakultäten beteiligt sind. Anträge aus nur einem Fachbereich werden nicht berücksichtigt."},{"id":"C","text":"Das Sprachenzentrum bietet im Sommer einen Intensivkurs Deutsch an. Der Unterricht findet vormittags statt. Für die Anmeldung ist ein B2-Zertifikat oder ein entsprechendes Ergebnis im Einstufungstest erforderlich."},{"id":"D","text":"Das Fahrradverleihsystem auf dem Campus wird erneuert. Die ersten 30 Minuten jeder Fahrt sind kostenlos, längere Nutzungszeiten werden berechnet. Für Studierende und Beschäftigte gelten dieselben Bedingungen."},{"id":"E","text":"Das Career Center bietet Absolventinnen und Absolventen Online-Beratung an. In den ersten zwei Jahren nach dem Abschluss ist dieser Service kostenlos, danach fällt eine Gebühr an."},{"id":"F","text":"Die theoretische Labor-Sicherheitsschulung kann vollständig online absolviert werden. Der praktische Teil muss dagegen persönlich auf dem Campus durchgeführt werden."}],"items":[{"q":"Wer braucht für die Nutzung außerhalb normaler Zeiten eine Karte?","a":"A"},{"q":"Wo ist Zusammenarbeit zwischen Fachbereichen Voraussetzung?","a":"B"},{"q":"Wo muss ein bestimmtes Sprachniveau nachgewiesen werden?","a":"C"},{"q":"Welches Angebot ist nur für kurze Nutzung vollständig kostenlos?","a":"D"},{"q":"Welches Angebot bleibt nach Abschluss nur zeitlich begrenzt gratis?","a":"E"},{"q":"Wo kann ein Teil digital, ein anderer aber nur vor Ort absolviert werden?","a":"F"}]},"reading3":{"text":"Peer-Review-Verfahren sollen wissenschaftliche Qualität sichern, indem Fachkolleginnen und Fachkollegen Manuskripte vor der Veröffentlichung prüfen. Das System ist jedoch nicht einheitlich. Bei manchen Zeitschriften kennen Gutachter die Namen der Autorinnen und Autoren, bei anderen bleiben beide Seiten anonym. Befürworter stärkerer Anonymisierung hoffen, dass institutionelles Prestige oder bekannte Namen weniger Einfluss haben. Vollständige Anonymität lässt sich in kleinen Fachgebieten allerdings oft nicht gewährleisten, weil Thema, Datensatz oder Zitierweise Rückschlüsse zulassen.\n\nKritisiert wird außerdem, dass Gutachten meist unbezahlt erstellt werden. Für Forschende ist diese Arbeit Teil der wissenschaftlichen Selbstverwaltung, konkurriert aber mit Forschung, Lehre und Verwaltung. Einige Verlage experimentieren deshalb mit Anerkennungssystemen, etwa dokumentierten Reviewer-Profilen oder formellen Zertifikaten. Eine direkte Bezahlung ist dagegen umstritten, weil sie neue Interessenkonflikte schaffen könnte.\n\nAuch Geschwindigkeit ist ein Problem. Ein sorgfältiges Gutachten braucht Zeit, während Autorinnen und Autoren Ergebnisse möglichst schnell veröffentlichen möchten. Preprints umgehen diese Verzögerung, indem Manuskripte bereits vor dem Peer Review öffentlich zugänglich gemacht werden. Dadurch kann Wissen schneller zirkulieren, doch die Texte sind zu diesem Zeitpunkt noch nicht formal begutachtet. Leser müssen den Status daher richtig einordnen.\n\nTrotz aller Kritik wird Peer Review nicht einfach als überholt betrachtet. Viele Fachleute sehen vielmehr Reformbedarf: transparentere Kriterien, bessere Anerkennung der Gutachterarbeit und klarere Kennzeichnung unterschiedlicher Veröffentlichungsstadien.","items":[{"q":"Bei allen Zeitschriften bleiben Autor und Gutachter anonym.","a":1},{"q":"Anonymisierung soll den Einfluss bekannter Namen reduzieren.","a":0},{"q":"In kleinen Fachgebieten kann Anonymität schwer sicherzustellen sein.","a":0},{"q":"Der Text nennt eine feste Zahl von Tagen, innerhalb derer jedes Peer-Review abgeschlossen sein muss.","a":2},{"q":"Zertifikate werden als mögliche Anerkennung erprobt.","a":0},{"q":"Direkte Bezahlung ist völlig unumstritten.","a":1},{"q":"Preprints erscheinen erst nach abgeschlossenem Peer Review.","a":1},{"q":"Preprints können Forschung schneller sichtbar machen.","a":0},{"q":"Der Text gibt an, wie hoch die Honorare für Gutachterinnen und Gutachter durchschnittlich sind.","a":2},{"q":"Der Text fordert die vollständige Abschaffung von Peer Review.","a":1},{"q":"Es wird Reformbedarf bei Kriterien und Anerkennung gesehen.","a":0}],"labels":["richtig","falsch","nicht im Text"],"heading":{"q":"Welche Überschrift passt am besten?","o":["Peer Review zwischen Qualitätssicherung und Reformbedarf","Warum wissenschaftliche Zeitschriften verschwinden","Die Geschichte der Universitätsbibliothek"],"a":0}},"languageBlocks":[{"q":"Die Ergebnisse ___ bereits im vergangenen Jahr veröffentlicht ___.","o":["haben / werden","sind / worden","wurden / geworden","sind / geworden"],"a":1,"why":"Perfekt Vorgangspassiv: sein + Partizip II + worden."},{"q":"An der Sitzung ___ ausführlich über die neue Prüfungsordnung diskutiert.","o":["wird worden","hat","ist geworden","wurde"],"a":3,"why":"Unpersönliches Vorgangspassiv."},{"q":"Die Tür ist seit acht Uhr ___.","o":["geschlossen","geschlossen worden","schließen","schloss"],"a":0,"why":"Zustandspassiv: sein + Partizip II."},{"q":"Die Forschenden ___ zu dem Ergebnis, dass weitere Daten nötig sind.","o":["machen","setzen","kommen","führen"],"a":2,"why":"Nomen-Verb-Verbindung: zu dem Ergebnis kommen."},{"q":"Die neue Regelung tritt im Januar in ___.","o":["Gang","Kraft","Folge","Sicht"],"a":1,"why":"Feste Verbindung: in Kraft treten."},{"q":"Die Aussage des Ministers ___ auf heftige Kritik.","o":["stieß","geriet","nahm","setzte"],"a":0,"why":"Feste Verbindung: auf Kritik stoßen."},{"q":"Nach den vorliegenden Daten ___ die Nachfrage in den nächsten Monaten steigen.","o":["soll","will","magst","dürfte"],"a":3,"why":"dürfte = wahrscheinliche Vermutung."},{"q":"Die Ursache ___ in einem technischen Defekt gelegen haben; alle anderen Möglichkeiten wurden ausgeschlossen.","o":["soll","will","muss","kann nur nicht"],"a":2,"why":"muss + Infinitiv Perfekt = starke Schlussfolgerung."},{"q":"Der Konzern ___ bereits seit Monaten von den Problemen gewusst haben. Das berichten mehrere Zeitungen.","o":["soll","muss","will","darf"],"a":0,"why":"soll = Information aus zweiter Hand."},{"q":"Der Zeuge ___ den Vorfall genau beobachtet haben, doch seine Angaben widersprechen sich.","o":["muss","will","darf","sollte"],"a":1,"why":"will = behauptete, vom Sprecher distanzierte Aussage."},{"q":"An Ihrer Stelle ___ ich die Daten vor der Veröffentlichung noch einmal prüfen.","o":["werde","war","wurde","würde"],"a":3,"why":"Konjunktiv II für Rat."},{"q":"Wenn die Finanzierung früher gesichert worden wäre, ___ das Projekt bereits begonnen.","o":["würde","wäre","hätte","sei"],"a":2,"why":"Irrealer Bedingungssatz Vergangenheit: hätte ... begonnen."},{"q":"Der Sprecher erklärte, die Verhandlungen ___ noch nicht abgeschlossen.","o":["sind","seien","wären gewesen","werden"],"a":1,"why":"Konjunktiv I der indirekten Rede."},{"q":"Die Autorin betonte, sie ___ die Daten selbst ausgewertet.","o":["habe","hat","hätte","würde haben"],"a":0,"why":"Indirekte Rede: sie habe ... ausgewertet."},{"q":"___ die Nachfrage stark gestiegen ist, wurde das Angebot erweitert.","o":["Trotz","Wegen","Da","Infolge"],"a":2,"why":"Kausaler Nebensatz mit da."},{"q":"___ des starken Anstiegs der Nachfrage wurde das Angebot erweitert.","o":["Da","Obwohl","Damit","Wegen"],"a":3,"why":"Nominalisierung: wegen + Genitiv."},{"q":"Die Maßnahme ist teuer. ___ könnte sie sich langfristig auszahlen.","o":["Daher","Dennoch","Folglich","Indem"],"a":1,"why":"Dennoch markiert eine Konzession."},{"q":"Die Studie zeigt einen Zusammenhang, ___ sie keine eindeutige Kausalität belegt.","o":["damit","sodass","wobei","deshalb"],"a":2,"why":"wobei kann eine einschränkende Zusatzinformation einleiten."},{"q":"Die Daten wurden anonymisiert, ___ Rückschlüsse auf einzelne Personen verhindert werden.","o":["damit","obwohl","denn","während"],"a":0,"why":"Finalsatz mit damit."},{"q":"Es handelt sich um ein Verfahren, ___ Zuverlässigkeit noch geprüft werden muss.","o":["deren","dem","das","dessen"],"a":3,"why":"Genitiv-Relativpronomen: dessen (Verfahren, Neutrum)."},{"q":"Die Ergebnisse sind nicht nur statistisch signifikant, ___ auch praktisch relevant.","o":["obwohl","sondern","jedoch","denn"],"a":1,"why":"Korrelat: nicht nur ..., sondern auch ..."},{"q":"Je genauer die Kriterien definiert sind, ___ lassen sich die Ergebnisse vergleichen.","o":["so dass besser","obwohl besser","desto besser","damit besser"],"a":2,"why":"Je ..., desto ..."}],"listening1":{"scripts":["Für meine Dissertation brauche ich einen ruhigen Arbeitsplatz. Das neue Großraumbüro ist modern, aber für konzentrierte Analyse ungeeignet.","Ich finde die neue Datenbank grundsätzlich gut, nur die Suchfilter sind so kompliziert, dass ich oft länger brauche als vorher.","Die internationale Summer School war fachlich stark. Besonders wertvoll waren für mich aber die Kontakte zu Forschenden aus anderen Ländern.","Online-Vorlesungen sind praktisch, wenn ich krank bin. Dauerhaft fehlt mir jedoch der direkte Austausch im Seminarraum.","Ich würde gern häufiger mit dem Fahrrad kommen, doch es gibt zu wenige sichere Abstellplätze am Campus.","Die Mensa hat mehr vegane Angebote als früher. Leider sind die Warteschlangen zwischen zwölf und eins inzwischen extrem lang.","Das Schreibzentrum hat mir nicht den Text korrigiert, sondern gezeigt, wie ich meine Argumentation selbst überarbeiten kann. Genau das war hilfreich.","Für den Statistik-Kurs wäre eine kurze Wiederholung der Grundlagen sinnvoll. Viele steigen direkt mit komplexer Software ein und verlieren den Anschluss."],"options":["A Ruhiger Arbeitsplatz fehlt","B Suchsystem schwer bedienbar","C Internationale Kontakte besonders wertvoll","D Präsenz-Austausch bleibt wichtig","E Fahrradinfrastruktur unzureichend","F Lange Wartezeit beim Essen","G Beratung fördert selbstständiges Überarbeiten","H Grundlagen fehlen","I Mehr Prüfungen gewünscht","J Wohnheim zu teuer"],"answers":[0,1,2,3,4,5,6,7]},"listening2":{"script":"Moderator: Frau Stein, Universitäten sprechen viel über interdisziplinäre Forschung. Warum ist sie so schwierig? Expertin: Weil Disziplinen nicht nur unterschiedliche Themen haben, sondern auch unterschiedliche Qualitätskriterien, Methoden und sogar Vorstellungen davon, was als überzeugender Beleg gilt. Moderator: Reicht es, Forschende aus zwei Fächern in ein Projekt zu setzen? Expertin: Nein. Wenn Rollen und Begriffe nicht früh geklärt werden, arbeiten Teams oft parallel statt gemeinsam. Erfolgreiche Projekte investieren am Anfang erstaunlich viel Zeit in gemeinsame Sprache. Moderator: Kostet das nicht Effizienz? Expertin: Kurzfristig ja. Langfristig verhindert es Missverständnisse. Ein zweiter Faktor ist Karrierebewertung. Wer interdisziplinär publiziert, findet manchmal schwerer die “richtige” Fachzeitschrift und wird in traditionellen Bewertungssystemen schlechter eingeordnet. Moderator: Was können Universitäten tun? Expertin: Gemeinsame Infrastruktur schaffen, Moderation finanzieren und bei Berufungs- oder Förderentscheidungen interdisziplinäre Beiträge angemessen anerkennen. Moderator: Ist Interdisziplinarität immer besser? Expertin: Nein. Sie ist sinnvoll, wenn die Forschungsfrage tatsächlich mehrere Perspektiven braucht. Ein Projekt wird nicht automatisch gut, nur weil viele Disziplinen beteiligt sind.","items":[{"q":"Warum ist interdisziplinäre Zusammenarbeit laut Stein anspruchsvoll?","o":["Weil Fächer unterschiedliche Methoden und Gütekriterien haben","Weil Forschende nicht kommunizieren dürfen","Weil nur zwei Fächer erlaubt sind"],"a":0},{"q":"Was reicht nicht aus?","o":["Gemeinsame Begriffe zu entwickeln","Menschen aus mehreren Fächern zusammenzusetzen","Rollen früh zu klären"],"a":1},{"q":"Wofür investieren erfolgreiche Teams am Anfang Zeit?","o":["Für gemeinsame Sprache und Begriffe","Nur für Budgetplanung","Für Publikation nach Projektende"],"a":0},{"q":"Wie bewertet Stein diese Anfangsinvestition?","o":["Kurzfristig aufwendig, langfristig nützlich","Völlig unnötig","Nur für große Unternehmen wichtig"],"a":0},{"q":"Welches Karriereproblem nennt sie?","o":["Interdisziplinäre Arbeit passt schlecht in traditionelle Bewertung","Es gibt zu viele Professuren","Publikationen sind verboten"],"a":0},{"q":"Was können Universitäten finanzieren?","o":["Moderation und gemeinsame Infrastruktur","Nur Einzelbüros","Private Reisen ohne Bezug"],"a":0},{"q":"Was soll bei Entscheidungen anerkannt werden?","o":["Interdisziplinäre Beiträge","Nur Anzahl der Arbeitsstunden","Alter der Forschenden"],"a":0},{"q":"Ist Interdisziplinarität immer überlegen?","o":["Ja","Nein","Nur im ersten Projektjahr"],"a":1},{"q":"Wann ist sie besonders sinnvoll?","o":["Wenn die Frage mehrere Perspektiven erfordert","Wenn ein Projekt wenig Zeit hat","Wenn keine Methode vorhanden ist"],"a":0},{"q":"Was macht ein Projekt laut Stein nicht automatisch gut?","o":["Viele beteiligte Disziplinen","Klare Begriffe","Passende Forschungsfrage"],"a":0}]},"listening3":{"script":"In meinem Vortrag geht es um wissenschaftliches Schreiben als Prozess. Erstens sollte die Fragestellung vor der eigentlichen Textproduktion präzisiert werden. Eine zu breite Frage führt fast zwangsläufig zu einem oberflächlichen Text. Zweitens lohnt es sich, Literatur nicht nur nach Themen, sondern nach Funktion zu ordnen: Welche Quelle liefert Theorie, welche Methode, welche Gegenposition? Drittens empfehle ich, eine Arbeitsgliederung früh anzulegen, sie aber nicht als unveränderlich zu behandeln. Beim Schreiben entstehen neue Zusammenhänge, die eine Umstrukturierung sinnvoll machen können. Viertens sollte die Überarbeitung in mehreren Durchgängen erfolgen. Inhaltliche Logik, Absatzstruktur und sprachliche Korrektheit sind unterschiedliche Ebenen; wer alles gleichzeitig korrigieren will, übersieht leicht Probleme. Fünftens ist Feedback besonders nützlich, wenn die schreibende Person konkrete Fragen stellt. “Ist der Text gut?” führt selten zu hilfreichen Antworten. “Ist die Verbindung zwischen Abschnitt zwei und drei nachvollziehbar?” ist wesentlich produktiver. Schließlich gehört Quellenmanagement von Beginn an zum Prozess. Fehlende Seitenzahlen oder unklare Dateinamen kurz vor der Abgabe zu rekonstruieren kostet unnötig Zeit.","items":[{"q":"1. Vor dem Schreiben soll die ______ präzisiert werden.","answers":["Fragestellung","Forschungsfrage"]},{"q":"2. Literatur kann nach ihrer ______ im Text geordnet werden.","answers":["Funktion","Rolle"]},{"q":"3. Eine frühe Gliederung soll nicht als ______ betrachtet werden.","answers":["unveränderlich","starr"]},{"q":"4. Neue Zusammenhänge können eine ______ nötig machen.","answers":["Umstrukturierung","Neustrukturierung"]},{"q":"5. Überarbeitung sollte in mehreren ______ erfolgen.","answers":["Durchgängen","Schritten"]},{"q":"6. Logik, Absatzstruktur und Sprache sind unterschiedliche ______.","answers":["Ebenen"]},{"q":"7. Für gutes Feedback sollte man ______ Fragen stellen.","answers":["konkrete","präzise"]},{"q":"8. Die Verbindung zwischen Abschnitten ist ein Beispiel für eine ______ Feedbackfrage.","answers":["konkrete","präzise"]},{"q":"9. Quellenmanagement soll von ______ an erfolgen.","answers":["Beginn","Anfang"]},{"q":"10. Fehlende Seitenzahlen kurz vor Abgabe kosten unnötig ______.","answers":["Zeit"]}]},"writingPrompts":[{"title":"Digitale Lehrmaterialien an Hochschulen","prompt":"Erörtern Sie, ob Hochschulen gedruckte Pflichtmaterialien weitgehend durch digitale Materialien ersetzen sollten. Berücksichtigen Sie Lernqualität, Kosten/Zugang, Nachhaltigkeit und Ihre eigene Position."},{"title":"Bewertung wissenschaftlicher Leistung","prompt":"Nehmen Sie Stellung dazu, ob wissenschaftliche Leistung stärker nach gesellschaftlicher Wirkung statt nach Publikationszahlen bewertet werden sollte. Gehen Sie auf Chancen, Probleme, Beispiele und eine mögliche Lösung ein."}],"speaking":{"presentationTopics":["Sollten Vorlesungen grundsätzlich aufgezeichnet werden?","Wie verändert künstliche Intelligenz wissenschaftliches Arbeiten?"],"summaryGuide":"Fassen Sie die Präsentation Ihres Partners bzw. Ihrer Partnerin in etwa 30–60 Sekunden zusammen: Hauptthese, zwei wesentliche Punkte und Schluss. Stellen Sie anschließend mindestens eine passende Anschlussfrage.","discussionQuote":"„Eine Universität sollte nicht Wissen vermitteln, sondern vor allem lehren, wie man Wissen kritisch prüft.“","discussionPoints":["Erläutern Sie das Zitat.","Begründen Sie, in welchen Punkten Sie zustimmen oder widersprechen.","Führen Sie ein konkretes Beispiel an.","Formulieren Sie eine gemeinsame Schlussfolgerung oder eine klare Differenz."]}},"dtb":{"overview":{"title":"Deutsch-Test für den Beruf C1","writtenMinutes":135,"speakingMinutes":16,"skills":{"reading":60,"listening":60,"writing":60,"speaking":60},"passTotal":144,"passSkill":36,"compensationMin":24},"reading":{"part1":{"people":["Mira möchte wissen, wie sie nach mehreren Jahren Berufserfahrung in eine Leitungsrolle hineinwachsen kann.","Deniz sucht Informationen dazu, wie Unternehmen ihre Arbeitszeiten familienfreundlicher organisieren.","Elif interessiert sich dafür, wie kleine Betriebe Kunden trotz großer Konkurrenz langfristig binden.","Kemal überlegt, ob eine berufliche Weiterbildung während einer Vollzeitstelle realistisch ist.","Seda möchte erfahren, wie Betriebe nachhaltiger einkaufen können, ohne die Kosten völlig aus dem Blick zu verlieren."],"articles":[{"title":"A · Führung lernen statt nur befördert werden","text":"Ein neues Mentoringprogramm begleitet Fachkräfte zwölf Monate lang beim Wechsel in erste Führungsverantwortung. Im Mittelpunkt stehen Delegation, Feedback und schwierige Gespräche."},{"title":"B · Mehr Kunden durch Rabattaktionen?","text":"Eine Studie untersucht, warum kurzfristige Preisnachlässe zwar Umsatz bringen, aber nicht automatisch die Kundenbindung stärken."},{"title":"C · Weiterbildung neben dem Beruf","text":"Mehrere Anbieter setzen auf modulare Abend- und Onlinekurse, die sich mit einer Vollzeitbeschäftigung verbinden lassen. Wichtig sind klare Zeitfenster und Unterstützung durch den Arbeitgeber."},{"title":"D · Nachhaltige Beschaffung mit Augenmaß","text":"Ein Praxisleitfaden zeigt, wie Lieferanten nach Umwelt- und Sozialkriterien bewertet werden können, ohne Wirtschaftlichkeit und Lieferfähigkeit zu vernachlässigen."},{"title":"E · Familienfreundliche Schichtmodelle","text":"Betriebe testen Wunschdienstpläne, Tauschbörsen und verlässliche Kernzeiten. Erste Auswertungen zeigen weniger kurzfristige Ausfälle."},{"title":"F · Wenn Teams zu groß werden","text":"Der Beitrag erläutert, warum sehr große Abteilungen häufiger Kommunikationsprobleme haben und wie Teilteams helfen können."},{"title":"G · Kundentreue im lokalen Handel","text":"Kleine Unternehmen punkten gegenüber Ketten durch persönliche Beratung, schnelle Reklamationsbearbeitung und nachvollziehbare Serviceversprechen."},{"title":"H · Pendeln kostet Energie","text":"Arbeitspsychologen beschreiben Belastungen langer Arbeitswege und mögliche Entlastung durch Homeoffice-Tage."}],"answers":[0,4,6,2,3]},"part2":{"texts":["Sicherheitsinformation: Besucherinnen und Besucher dürfen die Werkstatt nur in Begleitung betreten. Schutzbrillen sind im markierten Produktionsbereich verpflichtend. Mitarbeitende, die dort nur Unterlagen abgeben, müssen ebenfalls eine Schutzbrille tragen. Persönliche Schutzausrüstung liegt am Eingang bereit.","Datenschutzinformation: Kundendaten dürfen ausschließlich in den vorgesehenen Systemen gespeichert werden. Private Cloud-Dienste sind untersagt. Ausdrucke mit personenbezogenen Daten müssen nach Gebrauch in die verschlossenen Datenschutzbehälter gegeben werden. Bei Unsicherheiten ist zunächst die interne Datenschutzstelle zu kontaktieren."],"items":[{"q":"Auch Mitarbeitende, die nur kurz Unterlagen in den Produktionsbereich bringen, brauchen dort eine Schutzbrille.","o":["richtig","falsch"],"a":0},{"q":"Besucher dürfen die Werkstatt allein betreten, wenn sie Schutzkleidung tragen.","o":["richtig","falsch"],"a":1},{"q":"Wo dürfen Kundendaten gespeichert werden?","o":["In jedem verschlüsselten privaten Cloud-Dienst","Nur in den dafür vorgesehenen betrieblichen Systemen","Auf privaten Geräten, wenn sie passwortgeschützt sind"],"a":1},{"q":"Was soll bei einer Unsicherheit zum Datenschutz zuerst geschehen?","o":["Die Daten sofort löschen","Die interne Datenschutzstelle kontaktieren","Den Kunden um eine neue Einwilligung bitten"],"a":1}]},"part3":{"questions":["Ich soll seit Wochen zusätzliche Aufgaben übernehmen. Wie kann ich ansprechen, dass meine Kapazität erreicht ist, ohne unkooperativ zu wirken?","Mein Team arbeitet teils zu Hause, teils im Büro. Informationen gehen verloren. Wie könnten wir die Übergaben verbessern?","Ich würde gern eine berufliche Fortbildung machen, weiß aber nicht, wie ich das mit meiner Arbeitszeit verbinden kann.","Unsere neue Kollegin erhält von verschiedenen Personen widersprüchliche Anweisungen. Was können wir tun?"],"tips":["Vor einem Gespräch mit der Führungskraft würde ich konkrete Beispiele sammeln: Welche Aufgaben kamen hinzu, wie viel Zeit brauchen sie und welche Prioritäten kollidieren? So lässt sich sachlich über Entlastung oder Priorisierung sprechen.","Wir haben für hybride Arbeit ein kurzes digitales Übergabeprotokoll eingeführt. Am Ende des Tages werden offene Punkte, Zuständigkeiten und Fristen in drei Minuten dokumentiert.","Bei uns gibt es eine Lernzeit-Regel: Für anerkannte Fortbildungen können Mitarbeitende monatlich einige Arbeitsstunden nutzen. Frag Personalabteilung oder Betriebsrat, ob es bei euch etwas Ähnliches gibt.","Für die Einarbeitung sollte eine Person die fachliche Koordination übernehmen. Andere Kolleginnen und Kollegen können unterstützen, aber Änderungen werden zuerst mit dieser Person abgestimmt.","Ich würde einfach später ins Büro kommen. Bei mir ist morgens weniger Verkehr, deshalb spare ich viel Zeit.","Unser Team macht jeden Freitag ein gemeinsames Frühstück. Das verbessert die Stimmung, löst aber fachliche Probleme nicht automatisch."],"answers":[0,1,2,3]},"part4":{"text":"Protokoll Bereichsmeeting · Thema Kundenservice. Die Geschäftsführung berichtet, dass die Antwortzeiten im Support zuletzt deutlich gestiegen sind. Ursache seien vor allem unklare Zuständigkeiten bei komplexen Reklamationen. Die Serviceleitung schlägt vor, für solche Fälle eine feste Eskalationsgruppe einzurichten. Die IT weist darauf hin, dass im Ticketsystem bereits eine Funktion zur Priorisierung vorhanden ist, die bisher aber kaum genutzt wird. Beschluss: Die IT aktiviert bis Ende des Monats eine vereinfachte Prioritätsansicht und schult die Teamleitungen. Parallel erstellt die Serviceleitung eine Liste von Fällen, die direkt an die Eskalationsgruppe gehen. Der Vertrieb bittet darum, bei Großkunden weiterhin eine persönliche Rückmeldung innerhalb eines Arbeitstags zu garantieren. Die Geschäftsführung stimmt zu, verlangt aber, dass diese Zusage im CRM sichtbar dokumentiert wird. Für das nächste Quartal soll außerdem geprüft werden, ob wiederkehrende Reklamationsgründe systematisch ausgewertet werden können. Verantwortlich dafür sind Service und Qualitätsmanagement gemeinsam.","items":[{"q":"Was gilt als Hauptgrund für die längeren Antwortzeiten?","o":["Zu wenige Großkunden","Unklare Zuständigkeiten bei schwierigen Reklamationen","Ein Ausfall des Ticketsystems"],"a":1},{"q":"Was soll die IT bis Ende des Monats tun?","o":["Ein völlig neues Ticketsystem kaufen","Eine Prioritätsansicht vereinfachen und Teamleitungen schulen","Alle Reklamationen selbst bearbeiten"],"a":1},{"q":"Was wird für Großkunden beibehalten?","o":["Eine persönliche Rückmeldung innerhalb eines Arbeitstags","Ein Rabatt bei jeder Reklamation","Eine telefonische Hotline rund um die Uhr"],"a":0},{"q":"Wo soll die besondere Zusage für Großkunden dokumentiert werden?","o":["Im CRM","Im Intranet","Nur im Protokoll"],"a":0},{"q":"Wer soll wiederkehrende Reklamationsgründe auswerten?","o":["Vertrieb allein","IT und Geschäftsführung","Service und Qualitätsmanagement gemeinsam"],"a":2}]},"readWrite":{"context":"Teamleitung an Sie: Bitte antworten Sie Frau Kramer. Entschuldigen Sie sich für die verspätete Lieferung. Erklären Sie, dass ein Artikel kurzfristig nicht verfügbar war. Bieten Sie entweder Teillieferung morgen oder komplette Lieferung am Freitag an. Fragen Sie, welche Variante sie bevorzugt.\n\nKundin Frau Kramer: Guten Tag, wir warten seit Montag auf die bestellten Präsentationsmaterialien. Für Donnerstag ist eine wichtige Veranstaltung geplant. Bisher habe ich weder Ware noch eine verlässliche Information erhalten. Bitte teilen Sie mir umgehend mit, wann wir mit der Lieferung rechnen können.","items":[{"q":"Was ist das Hauptproblem der Kundin?","o":["Die Rechnung ist zu hoch","Die Lieferung ist verspätet und der Termin ist kritisch","Sie möchte die Bestellung erweitern"],"a":1},{"q":"Welche zwei Lösungen soll die Antwort anbieten?","o":["Rabatt oder Stornierung","Teillieferung morgen oder vollständige Lieferung am Freitag","Abholung heute oder neue Bestellung nächste Woche"],"a":1}],"task":"Schreiben Sie Frau Kramer eine professionelle E-Mail. Setzen Sie alle Punkte der Teamleitung um und wählen Sie einen angemessenen Grad an Formalität."}},"listening":{"part1":{"conversations":[{"script":"Leiterin: Zwei Kolleginnen sind diese Woche krank. Wir schaffen die Hotline so nicht. Vorgesetzter: Für die nächsten Tage kann das Backoffice jeweils zwei Stunden unterstützen. Bitte erstelle zusätzlich einen Plan, welche Anfragen wirklich sofort bearbeitet werden müssen. Leiterin: Gut, dann haben wir zumindest eine Übergangslösung.","items":[{"q":"Die Teamleiterin sucht eine kurzfristige Lösung für personelle Ausfälle.","o":["richtig","falsch"],"a":0},{"q":"Was soll die Teamleiterin zusätzlich vorbereiten?","o":["Eine Prioritätenliste für Anfragen","Eine externe Stellenausschreibung","Einen Urlaubsplan"],"a":0}]},{"script":"Kollege: Im Lager werden dieselben Fehler immer wieder unterschiedlich dokumentiert. Kollegin: Dann können wir die Ursachen kaum auswerten. Lass uns ein einheitliches Formular testen und nach zwei Wochen schauen, ob es funktioniert. Kollege: Einverstanden, aber bitte so kurz, dass es im Alltag wirklich genutzt wird.","items":[{"q":"Die beiden wollen die Fehlerdokumentation vereinheitlichen.","o":["richtig","falsch"],"a":0},{"q":"Welche Bedingung nennt der Kollege?","o":["Das Formular soll sehr ausführlich sein","Das Formular soll im Alltag schnell nutzbar sein","Nur Führungskräfte sollen es ausfüllen"],"a":1}]},{"script":"Vertrieb: Unsere Bestandskunden bestellen stabil, aber wir gewinnen kaum neue Firmen. Marketing: Dann sollten wir die Testpakete gezielt an Interessenten schicken, die schon auf Messen Kontakt mit uns hatten. Vertrieb: Gute Idee. Ein allgemeiner Rabatt für alle wäre mir zu teuer.","items":[{"q":"Das Unternehmen hat vor allem Schwierigkeiten, neue Firmenkunden zu gewinnen.","o":["richtig","falsch"],"a":0},{"q":"Welche Maßnahme wird bevorzugt?","o":["Allgemeiner Rabatt für alle","Gezielte Testpakete für bereits interessierte Kontakte","Preiserhöhung für Bestandskunden"],"a":1}]}]},"part2":{"scripts":["Ich halte einen Abteilungswechsel nicht für eine Niederlage. Wenn jemand in einem anderen Bereich seine Stärken besser einsetzen kann, profitieren am Ende beide Teams.","Bei jeder Umstrukturierung neue Organigramme zu zeichnen, löst unser eigentliches Problem nicht. Wir müssen zuerst klären, wer welche Entscheidung treffen darf.","Offene Büros funktionieren nur, wenn es Rückzugsräume gibt. Sonst wird aus “mehr Austausch” schnell dauernde Unterbrechung.","Kontinuität ist wichtig, aber nicht um jeden Preis. Wenn Prozesse seit Jahren niemand mehr hinterfragt, wird Stabilität zum Stillstand."],"options":["A Ein Wechsel kann neue berufliche Möglichkeiten eröffnen.","B Kündigung ist meist die beste Lösung.","C Strukturen helfen nur, wenn Zuständigkeiten klar sind.","D Offene Arbeitsformen brauchen auch Rückzugsmöglichkeiten.","E Veränderungen sollten grundsätzlich vermieden werden.","F Zu viel unveränderte Routine kann Fortschritt behindern."],"answers":[0,2,3,5]},"part3":{"script":"Guten Morgen zusammen. Ich möchte kurz die Ergebnisse unseres ersten Halbjahres vorstellen. Der Umsatz liegt sechs Prozent über dem Vorjahreswert. Das liegt allerdings nicht daran, dass wir deutlich mehr Stück verkauft hätten; vielmehr konnten wir bei zwei Produktlinien höhere Preise durchsetzen. Bei den Serviceverträgen haben wir unser Ziel dagegen noch nicht erreicht. Dort fehlen uns vor allem Abschlüsse bei mittelgroßen Kunden. Für das zweite Halbjahr plant der Vertrieb deshalb eine gezielte Kampagne. Positiv ist die Entwicklung bei den Kosten: Durch neue Lieferverträge liegen die Materialkosten niedriger als geplant. Einen allgemeinen Personalabbau wird es nicht geben. In der Logistik brauchen wir sogar zusätzliche Kapazität, weil ab September ein neuer Großkunde beliefert wird. Für alle anderen Bereiche gilt zunächst der aktuelle Stellenplan.","items":[{"q":"Warum ist der Umsatz gestiegen?","o":["Vor allem wegen höherer Stückzahlen","Unter anderem wegen höherer Preise bei zwei Produktlinien","Weil Serviceverträge das Ziel übertroffen haben"],"a":1},{"q":"Wo wurde das Ziel noch nicht erreicht?","o":["Bei Serviceverträgen","Bei Materialkosten","Bei Großkunden in der Logistik"],"a":0},{"q":"Wie haben sich die Materialkosten entwickelt?","o":["Sie liegen unter Plan","Sie liegen deutlich über Plan","Dazu gibt es keine Aussage"],"a":0},{"q":"Was ist beim Personal geplant?","o":["Allgemeiner Abbau","Zusätzliche Kapazität in der Logistik","Neue Stellen in allen Bereichen"],"a":1}]},"part4":{"messages":[{"script":"Hallo, hier ist Frau Berger aus der Personalabteilung. Die Unterweisung morgen beginnt nicht um neun, sondern erst um zehn Uhr. Bitte informieren Sie auch Herrn Yilmaz aus Ihrem Team. Danke.","q":"Was soll getan werden?","o":["Die Unterweisung absagen","Herrn Yilmaz über die neue Uhrzeit informieren","Frau Berger um neun Uhr anrufen"],"a":1},{"script":"Guten Tag, Schneider vom Lieferanten ProPack. Die angekündigten Kartons kommen heute nicht mehr. Wir liefern morgen bis elf Uhr. Bitte prüfen Sie, ob die Anlieferung dann noch in Ihr Zeitfenster passt.","q":"Worum bittet Herr Schneider?","o":["Um Bestätigung des neuen Lieferzeitfensters","Um eine neue Bestellung","Um sofortige Abholung"],"a":0},{"script":"Hi, hier ist Jana. Ich habe die Präsentation für den Kunden fast fertig. Die aktuellen Umsatzzahlen fehlen mir noch. Kannst du mir bitte die Datei aus dem Monatsreport weiterleiten?","q":"Was braucht Jana?","o":["Die aktuelle Umsatzdatei","Eine Kundenadresse","Einen neuen Präsentationstermin"],"a":0},{"script":"Guten Morgen, Arslan hier. Unser Fahrer steht seit zwanzig Minuten am Tor 3, aber die Zufahrt ist gesperrt. Bitte rufen Sie ihn kurz zurück und sagen Sie ihm, welches Tor er nutzen soll.","q":"Was ist zu tun?","o":["Die Lieferung stornieren","Den Fahrer zurückrufen und eine andere Zufahrt nennen","Tor 3 öffnen lassen"],"a":1},{"script":"Hallo, Meier aus dem Einkauf. Für die Besprechung am Nachmittag brauche ich noch den aktuellen Preisvergleich. Wenn Sie ihn bis 14 Uhr ins Projektlaufwerk stellen könnten, wäre das super.","q":"Was erwartet Herr Meier?","o":["Eine neue Preisanfrage","Den Preisvergleich bis 14 Uhr im Projektlaufwerk","Eine Terminverschiebung"],"a":1}]},"hearWrite":{"script":"Guten Tag, hier ist Anja Reuter von der Firma Nordlicht, Telefonnummer 040 731 8842. Es geht um unsere Bestellung 7814. Wir benötigen die 30 Präsentationsständer nicht mehr am Freitag, sondern bereits am Donnerstagvormittag, weil unser Messestand früher aufgebaut wird. Falls das nicht möglich ist, rufen Sie mich bitte heute bis 16 Uhr zurück. Prüfen Sie bitte zuerst, ob der frühere Liefertermin machbar ist, und geben Sie mir dann kurz Bescheid.","reason":{"q":"Grund für den Anruf","o":["Angebot","Bestellung/Liefertermin","Beschwerde"],"a":1},"expected":{"name":"Anja Reuter","phone":"040 731 8842","info":["Bestellung 7814","30 Präsentationsständer","Donnerstagvormittag","Messestand früher aufgebaut"],"todo":"früheren Liefertermin prüfen und Rückmeldung geben"}}},"languageWriting":{"blocks1":{"text":"Betreff: Starttermin und Dienstreise\nSehr geehrte Frau Lorenz, vielen Dank für Ihre Nachricht. ___ habe ich meinen bisherigen Arbeitgeber über den geplanten Wechsel informiert. Er wäre bereit, auf einen Teil der Kündigungsfrist zu ___. Allerdings habe ich für die erste Oktoberwoche bereits seit Monaten eine Reise ___. Ich würde diese nur ungern ___. Könnten Sie mir bitte mitteilen, unter welchen ___ eine Verschiebung meines Starttermins möglich wäre? Gerne komme ich dafür noch einmal zu einem persönlichen ___ vorbei.","options":["Bedingungen","gebucht","Gespräch","inzwischen","stornieren","verzichten","bestätigen","kaum","Rückfragen","Voraussetzung"],"answers":[3,5,1,4,0,2]},"blocks2":{"text":"Interne Nachricht: ___ verzögert sich die Freigabe unseres neuen Katalogs. Wenn wir den Kunden nicht bis nächste Woche ___, müssen wir den Zeitplan anpassen. ___ ist das zwar unangenehm, aber wir sollten die zusätzlichen Abstimmungen ___. Bitte gib mir kurz Bescheid, ___ mit dem Designteam so organisieren lässt und ___ wir die Druckerei informieren sollen.","items":[{"q":"Lücke 1","o":["Wie befürchtet","Als befürchten","Mit Befürchtung"],"a":0},{"q":"Lücke 2","o":["vertrösten können","zu vertrösten haben","vertröstet wollen"],"a":0},{"q":"Lücke 3","o":["Aus meiner Sicht","Zu meiner Sicht","Von meiner Sicht"],"a":0},{"q":"Lücke 4","o":["in Kauf nehmen","in Anspruch nehmen","außer Kraft setzen"],"a":0},{"q":"Lücke 5","o":["ob sich das","wann ihr das","warum dies"],"a":0},{"q":"Lücke 6","o":["wann","obwohl","sobald"],"a":0}]},"statementPrompts":[{"title":"Verbindlicher Weiterbildungstag","prompt":"Die Geschäftsführung erwägt, für alle Mitarbeitenden pro Quartal einen verpflichtenden Weiterbildungstag einzuführen. Wägen Sie Vor- und Nachteile ab, nennen Sie passende Beispiele, legen Sie Ihren Standpunkt dar und ziehen Sie ein Fazit."},{"title":"Feste Präsenztage für alle Teams","prompt":"Die Geschäftsführung plant, zwei feste Präsenztage pro Woche für alle Teams einzuführen. Wägen Sie Vor- und Nachteile ab, nennen Sie passende Beispiele, legen Sie Ihren Standpunkt dar und ziehen Sie ein Fazit."}]},"speaking":{"topics":["Welche Eigenschaften sollte eine gute Führungskraft haben?","Welche Rolle spielt Weiterbildung im Berufsleben?","Homeoffice: Welche Chancen und Grenzen sehen Sie?","Wie können Besprechungen effizienter werden?","Was macht gute Zusammenarbeit in internationalen Teams aus?","Wie wichtig ist Feedback am Arbeitsplatz?","Sollten Unternehmen flexible Arbeitszeiten stärker fördern?","Wie verändert künstliche Intelligenz den Arbeitsalltag?","Welche Bedeutung hat Nachhaltigkeit für Unternehmen?","Wie kann die Einarbeitung neuer Kolleginnen und Kollegen verbessert werden?","Was hilft gegen Stress im Berufsalltag?","Wie wichtig ist guter Kundenservice für den Erfolg eines Unternehmens?"],"examinerQuestions":["Können Sie ein konkretes Beispiel nennen?","Welche Nachteile könnte Ihre Position haben?","Wie ist die Situation in einem Betrieb, den Sie kennen?","Was würden Sie einer Führungskraft konkret empfehlen?"],"smallTalk":["Arbeitsweg und Pendeln","Pausengestaltung im Arbeitsalltag","Sport und Bewegung nach der Arbeit","Kinderbetreuung und Arbeitszeiten","Mittagessen im Betrieb","Urlaubsplanung im Team"],"problems":[{"title":"Falsche Lieferung an wichtigen Kunden","text":"Ein wichtiger Kunde hat die falsche Ware erhalten und braucht die richtige Lieferung spätestens morgen. Besprechen Sie Sofortmaßnahmen, Kundenkommunikation, interne Ursachenklärung und langfristige Verbesserungen."},{"title":"Neue Kollegin ohne klare Einarbeitung","text":"Eine neue Kollegin erhält widersprüchliche Informationen und macht deshalb Fehler. Besprechen Sie kurzfristige Unterstützung, Zuständigkeiten, einen Einarbeitungsplan und langfristige Verbesserungen."},{"title":"Viele Beschwerden über lange Antwortzeiten","text":"Der Kundenservice erhält zunehmend Beschwerden über langsame Rückmeldungen. Besprechen Sie Prioritäten, Aufgabenverteilung, Kommunikation mit Kunden und nachhaltige Prozessverbesserungen."}]}}};
